window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[23]={"2300":{"example:2300:exzh":"I'll use this formula to solve the problem.","example:2300:exzh2":"It's important to use the formula when calculating.","example:2300:exzh3":"I memorized the formula in math class.","example:2300:exzh4":"This formula is essential to physics.","example:2300:exzh5":"Memorizing formulas helps on exams."},"2301":{"example:2301:exzh":"My idea is almost right.","example:2301:exzh2":"This part is almost finished.","example:2301:exzh3":"She exercises almost every day.","example:2301:exzh4":"Almost everyone will take part.","example:2301:exzh5":"The exam results were mostly good."},"2302":{"example:2302:exzh":"I'm studying psychology.","example:2302:exzh2":"It's hard to understand his mindset.","example:2302:exzh3":"Human psychology is complex.","example:2302:exzh4":"We need to deal with psychological problems.","example:2302:exzh5":"I took a psychological test."},"2303":{"example:2303:exzh":"I have some errands to run today.","example:2303:exzh2":"I have something to do later, so I can't go.","example:2303:exzh3":"I have something important to do this weekend.","example:2303:exzh4":"I'll get in touch once I'm done with my errands.","example:2303:exzh5":"If there's anything you need, let me know."},"2304":{"example:2304:exzh":"Please take a look at the diagram.","example:2304:exzh2":"This diagram is very easy to understand.","example:2304:exzh3":"There are lots of diagrams in the textbook.","example:2304:exzh4":"I'll explain using a diagram.","example:2304:exzh5":"Please pay attention to this diagram."},"2305":{"example:2305:exzh":"I was late for school.","example:2305:exzh2":"I'll be careful not to be late.","example:2305:exzh3":"He was late for work.","example:2305:exzh4":"You'll get scolded if you're late.","example:2305:exzh5":"I explained the reason for being late.","grammar:2305:ex:trans":"I was late for school.","grammar:2305:ex:structure":"学校に遅刻しました","grammar:2305:ex:explain":"「遅刻する」 is a Sino-Japanese verb meaning to be late, and the thing you are late for takes 「に」: 「学校に遅刻する」 = to be late for school. 「遅刻しました」 is the polite past form. The whole sentence = I was late for school. Key point: the 「に」 in 「〜に遅刻する」 marks the place or event you are late for, as in 「会議に遅刻する」 (to be late for a meeting); don't use 「を」.","grammar:2305:ex:words:0:zh":"school","grammar:2305:ex:words:0:note":"がっこう","grammar:2305:ex:words:0:pos":"noun","grammar:2305:ex:words:1:zh":"(object)","grammar:2305:ex:words:1:pos":"particle","grammar:2305:ex:words:2:zh":"was late","grammar:2305:ex:words:2:note":"ちこくしました","grammar:2305:ex:words:2:pos":"verb","grammar:2305:ex:points:0":"❗遅刻（ちこく）する：to be late; 〜に遅刻 = to be late for ... (the target takes に).","grammar:2305:ex:points:1":"遅刻する: to be late.","grammar:2305:ex2:trans":"I'll be careful not to be late.","grammar:2305:ex2:structure":"遅刻しないように気をつけます","grammar:2305:ex2:words:0:zh":"so as not to be late","grammar:2305:ex2:words:0:note":"ちこくしない","grammar:2305:ex2:words:0:pos":"verb","grammar:2305:ex2:words:1:zh":"so as not to…","grammar:2305:ex2:words:1:pos":"auxiliary verb","grammar:2305:ex2:words:2:zh":"(made adverbial)","grammar:2305:ex2:words:2:pos":"particle","grammar:2305:ex2:words:3:zh":"be careful","grammar:2305:ex2:words:3:note":"きをつけます","grammar:2305:ex2:words:3:pos":"verb","grammar:2305:ex2:points:0":"❗〜ないように気をつける：to be careful not to ...; 気をつける = to be careful.","grammar:2305:ex2:points:1":"気をつける: be careful.","grammar:2305:ex3:trans":"He was late for work.","grammar:2305:ex3:structure":"仕事に遅刻しました","grammar:2305:ex3:words:0:zh":"he","grammar:2305:ex3:words:0:note":"かれ","grammar:2305:ex3:words:0:pos":"pronoun","grammar:2305:ex3:words:1:zh":"(topic)","grammar:2305:ex3:words:1:pos":"particle","grammar:2305:ex3:words:2:zh":"work","grammar:2305:ex3:words:2:note":"しごと","grammar:2305:ex3:words:2:pos":"noun","grammar:2305:ex3:words:3:zh":"(object)","grammar:2305:ex3:words:3:pos":"particle","grammar:2305:ex3:words:4:zh":"was late","grammar:2305:ex3:words:4:note":"ちこくしました","grammar:2305:ex3:words:4:pos":"verb","grammar:2305:ex3:points:0":"❗仕事に遅刻：to be late for work.","grammar:2305:ex3:points:1":"仕事に遅刻：being late for work.","grammar:2305:ex4:trans":"If you're late, you'll get scolded.","grammar:2305:ex4:structure":"遅刻すると怒られます","grammar:2305:ex4:words:0:zh":"be late","grammar:2305:ex4:words:0:note":"ちこくする","grammar:2305:ex4:words:0:pos":"verb","grammar:2305:ex4:words:1:zh":"(as soon as…)","grammar:2305:ex4:words:1:pos":"particle","grammar:2305:ex4:words:2:zh":"get scolded","grammar:2305:ex4:words:2:note":"おこられます","grammar:2305:ex4:words:2:pos":"verb","grammar:2305:ex4:points:0":"❗怒られる：to get scolded (passive form of 怒る); 〜と = as soon as …, then ….","grammar:2305:ex4:points:1":"怒られる：to get scolded.","grammar:2305:ex5:trans":"I explained the reason for being late.","grammar:2305:ex5:structure":"遅刻の理由を説明しました","grammar:2305:ex5:words:0:zh":"be late","grammar:2305:ex5:words:0:note":"ちこく","grammar:2305:ex5:words:0:pos":"noun","grammar:2305:ex5:words:1:zh":"'s","grammar:2305:ex5:words:1:pos":"particle","grammar:2305:ex5:words:2:zh":"reason","grammar:2305:ex5:words:2:note":"りゆう","grammar:2305:ex5:words:2:pos":"noun","grammar:2305:ex5:words:3:zh":"(object marker)","grammar:2305:ex5:words:3:pos":"particle","grammar:2305:ex5:words:4:zh":"explained","grammar:2305:ex5:words:4:note":"せつめいしました","grammar:2305:ex5:words:4:pos":"verb","grammar:2305:ex5:points:0":"❗遅刻の理由：the reason for being late.","grammar:2305:ex5:points:1":"遅刻の理由：the cause of being late."},"2306":{"example:2306:exzh":"I'll register under a temporary name.","example:2306:exzh2":"This is a tentative plan.","example:2306:exzh3":"We need a temporary configuration.","example:2306:exzh4":"I'm doing temporary work.","example:2306:exzh5":"I checked the temporary state."},"2307":{"example:2307:exzh":"I'm a member of this group.","example:2307:exzh2":"She's a member of the team.","example:2307:exzh3":"I'll treat it as a member of the family and take good care of it.","example:2307:exzh4":"I'll take part as a member of this organization.","example:2307:exzh5":"He's a member of the company."},"2308":{"example:2308:exzh":"We have a hideout in the mountains.","example:2308:exzh2":"You can spend quiet time at this hideout.","example:2308:exzh3":"The hideout is perfect for hanging out with friends.","example:2308:exzh4":"The hideout plays an important role in the movie.","example:2308:exzh5":"The children want to build their own hideout."},"2309":{"example:2309:exzh":"This discount is available for a limited time.","example:2309:exzh2":"The submission period for homework ends tomorrow.","example:2309:exzh3":"The travel period is one week.","example:2309:exzh4":"Exam period is very stressful.","example:2309:exzh5":"You can extend the internship period."},"2310":{"example:2310:exzh":"Everyone should be treated fairly.","example:2310:exzh2":"We need fair rules.","example:2310:exzh3":"Fairness is important in this match.","example:2310:exzh4":"He makes fair and impartial judgments.","example:2310:exzh5":"Let's aim for a fair society."},"2311":{"example:2311:exzh":"The condition is getting worse.","example:2311:exzh2":"The worsening of environmental problems is serious.","example:2311:exzh3":"This medicine prevents symptoms from getting worse.","example:2311:exzh4":"There is concern about the worsening economic situation.","example:2311:exzh5":"We need to discuss climate change, which is getting worse."},"2312":{"example:2312:exzh":"She will take a new course.","example:2312:exzh2":"This mountain trail is difficult.","example:2312:exzh3":"Choosing a course is important.","example:2312:exzh4":"He has run a full marathon course before.","example:2312:exzh5":"I plan to sign up for a new course."},"2313":{"example:2313:exzh":"I sometimes go to see movies.","example:2313:exzh2":"He is sometimes late.","example:2313:exzh3":"On holidays, I sometimes hang out with friends.","example:2313:exzh4":"I sometimes feel like eating sweets.","example:2313:exzh5":"I sometimes cook for myself."},"2315":{"example:2315:exzh":"We need a new design pattern.","example:2315:exzh2":"This pattern is very popular.","example:2315:exzh3":"Let's try changing the pattern.","example:2315:exzh4":"She looks at the pattern and thinks.","example:2315:exzh5":"That pattern is interesting."},"2316":{"example:2316:exzh":"He shed tears.","example:2316:exzh2":"I laughed so hard that tears came to my eyes.","example:2316:exzh3":"I watched a sad movie and tears came out.","example:2316:exzh4":"She wiped her tears.","example:2316:exzh5":"I'm so happy I could cry."},"2317":{"example:2317:exzh":"An accident was caused.","example:2317:exzh2":"He caused a problem.","example:2317:exzh3":"The new law might cause confusion.","example:2317:exzh4":"That decision caused controversy.","example:2317:exzh5":"Warming causes abnormal weather."},"2318":{"example:2318:exzh":"This country is strengthening its military power.","example:2318:exzh2":"Military issues are important.","example:2318:exzh3":"He is interested in military affairs.","example:2318:exzh4":"Military training is being carried out.","example:2318:exzh5":"She attends a military academy."},"2319":{"example:2319:exzh":"In general, you need to follow this directive.","example:2319:exzh2":"The directive has been issued.","example:2319:exzh3":"This directive is important.","example:2319:exzh4":"Please act according to the directive.","example:2319:exzh5":"The unit received the directive."},"2320":{"example:2320:exzh":"He works as the president's bodyguard.","example:2320:exzh2":"Bodyguard work is tough.","example:2320:exzh3":"There are times when a bodyguard is needed.","example:2320:exzh4":"The security guard handles protection duties.","example:2320:exzh5":"She has bodyguards accompanying her."},"2321":{"example:2321:exzh":"They have been a married couple for a long time.","example:2321:exzh2":"The couple went on a trip together.","example:2321:exzh3":"This couple gets along well.","example:2321:exzh4":"There is joy in married life.","example:2321:exzh5":"A new couple has formed."},"2324":{"example:2324:exzh":"The criminal was caught by him.","example:2324:exzh2":"I was caught right away.","example:2324:exzh3":"I thought about running away, but I was caught.","example:2324:exzh4":"The thief was caught by the police at the station.","example:2324:exzh5":"The mouse was caught by the cat.","grammar:2324:ex:trans":"The criminal was caught by him.","grammar:2324:ex:structure":"〜は〜に捕まった","grammar:2324:ex:explain":"「犯人は」 marks the one who gets caught, and 「彼に」 indicates the person who caught the criminal. 「捕まった」 is the past form of 「捕まる」; although the meaning comes out as passive in English, the Japanese sentence does not use the passive auxiliary 「れる／られる」.","grammar:2324:ex:words:0:zh":"culprit","grammar:2324:ex:words:0:note":"はんにん","grammar:2324:ex:words:0:pos":"noun","grammar:2324:ex:words:1:zh":"(topic)","grammar:2324:ex:words:1:pos":"particle","grammar:2324:ex:words:2:zh":"he","grammar:2324:ex:words:2:note":"かれ","grammar:2324:ex:words:2:pos":"pronoun","grammar:2324:ex:words:3:zh":"(the person who does the catching)","grammar:2324:ex:words:3:pos":"particle","grammar:2324:ex:words:4:zh":"to be caught","grammar:2324:ex:words:4:note":"つかまっ","grammar:2324:ex:words:4:pos":"verb","grammar:2324:ex:words:5:zh":"(past, completed)","grammar:2324:ex:words:5:pos":"auxiliary verb","grammar:2324:ex:points:0":"「捕まる」 is itself an intransitive verb meaning to get caught, not a passive form.","grammar:2324:ex:points:1":"In 「人に捕まる」, the 「に」 marks the person who does the catching.","grammar:2324:ex2:trans":"Got caught right away.","grammar:2324:ex2:structure":"すぐに捕まってしまった","grammar:2324:ex2:words:0:zh":"soon","grammar:2324:ex2:words:0:pos":"adverb","grammar:2324:ex2:words:1:zh":"got caught","grammar:2324:ex2:words:1:note":"つかまって","grammar:2324:ex2:words:1:pos":"verb","grammar:2324:ex2:words:2:zh":"(with regret)","grammar:2324:ex2:words:2:pos":"auxiliary verb","grammar:2324:ex2:points:0":"❗捕まる (intransitive verb): to be caught, to get caught; 〜てしまう = (regrettably) ended up …","grammar:2324:ex2:points:1":"捕まる: getting caught.","grammar:2324:ex3:trans":"I wanted to run away, but I got caught.","grammar:2324:ex3:structure":"〜と思ったが、捕まった","grammar:2324:ex3:words:0:zh":"wanted to run away","grammar:2324:ex3:words:0:note":"にげよう","grammar:2324:ex3:words:0:pos":"verb","grammar:2324:ex3:words:1:zh":"(quotation)","grammar:2324:ex3:words:1:pos":"particle","grammar:2324:ex3:words:2:zh":"thought up","grammar:2324:ex3:words:2:note":"おもった","grammar:2324:ex3:words:2:pos":"verb","grammar:2324:ex3:words:3:zh":"but","grammar:2324:ex3:words:3:pos":"particle","grammar:2324:ex3:words:4:zh":"got arrested","grammar:2324:ex3:words:4:note":"つかまった","grammar:2324:ex3:words:4:pos":"verb","grammar:2324:ex3:points:0":"❗〜ようと思う: to intend to …; 捕まった = was caught (intransitive verb).","grammar:2324:ex3:points:1":"捕まった: got caught.","grammar:2324:ex4:trans":"The thief was caught by the police at the station.","grammar:2324:ex4:structure":"人は＋場所で＋警察に＋捕まりました","grammar:2324:ex4:words:0:zh":"thief","grammar:2324:ex4:words:0:note":"どろぼう; a person who steals things","grammar:2324:ex4:words:0:pos":"noun","grammar:2324:ex4:words:1:zh":"marks the topic","grammar:2324:ex4:words:1:pos":"particle","grammar:2324:ex4:words:2:zh":"station","grammar:2324:ex4:words:2:note":"えき; a place where you catch trains","grammar:2324:ex4:words:2:pos":"noun","grammar:2324:ex4:words:3:zh":"spot","grammar:2324:ex4:words:3:pos":"particle","grammar:2324:ex4:words:4:zh":"police","grammar:2324:ex4:words:4:note":"けいさつ; the police","grammar:2324:ex4:words:4:pos":"noun","grammar:2324:ex4:words:5:zh":"the one doing the action","grammar:2324:ex4:words:5:pos":"particle","grammar:2324:ex4:words:6:zh":"got caught","grammar:2324:ex4:words:6:note":"つかまり; the stem of the masu-form","grammar:2324:ex4:words:6:pos":"verb","grammar:2324:ex4:words:7:zh":"polite past","grammar:2324:ex4:words:7:pos":"auxiliary verb","grammar:2324:ex4:points:0":"「警察に捕まりました」 means was caught by the police; 「捕まる」 is itself an intransitive verb that already means to get caught, so there is no need to turn it into a passive form.","grammar:2324:ex4:points:1":"The 「に」 in 「警察に」 marks the side doing the catching; the active way to say it is 「警察が泥棒を捕まえました」.","grammar:2324:ex4:points:2":"In 「駅で」, 「で」 marks the place where the event happens.","grammar:2324:ex5:trans":"The mouse was caught by the cat.","grammar:2324:ex5:structure":"〜が〜に捕まった","grammar:2324:ex5:explain":"This sentence takes the mouse as its subject and describes the result of it falling into the cat's clutches. 「猫に」 indicates the side that caught the mouse, and 「捕まった」 shows that it has already happened; the matching transitive way to say it is that the cat caught the mouse.","grammar:2324:ex5:words:0:zh":"mouse","grammar:2324:ex5:words:0:pos":"noun","grammar:2324:ex5:words:1:zh":"(nominative)","grammar:2324:ex5:words:1:pos":"particle","grammar:2324:ex5:words:2:zh":"cat","grammar:2324:ex5:words:2:note":"ねこ","grammar:2324:ex5:words:2:pos":"noun","grammar:2324:ex5:words:3:zh":"(the side doing the catching)","grammar:2324:ex5:words:3:pos":"particle","grammar:2324:ex5:words:4:zh":"to be caught","grammar:2324:ex5:words:4:note":"つかまっ","grammar:2324:ex5:words:4:pos":"verb","grammar:2324:ex5:words:5:zh":"(past, completed)","grammar:2324:ex5:words:5:pos":"auxiliary verb","grammar:2324:ex5:points:0":"「捕まる」 is an intransitive verb, so the mouse that gets caught is marked with 「が」.","grammar:2324:ex5:points:1":"When you rephrase it as 「猫がネズミを捕まえた」, you use the transitive verb 「捕まえる」."},"2325":{"example:2325:exzh":"It has started to snow.","example:2325:exzh2":"I want to build a snowman.","example:2325:exzh3":"Snow is beautiful.","example:2325:exzh4":"Snowy days are fun.","example:2325:exzh5":"I like walking on snowy roads.","grammar:2325:ex:trans":"It has started to snow.","grammar:2325:ex:structure":"雪が降ってきた","grammar:2325:ex:explain":"Same pattern as the earlier 「雨が降ってきた」. 「雪が降る」 = to snow, with 「が」 marking the subject. 「降ってきた」 is 「降る」 + 「てくる」 = to start snowing; 「〜てくる」 expresses a phenomenon starting to appear and developing toward the present. The whole sentence means \"It has started to snow.\" Key point: here 「〜てくる」 shows a change from absence to presence (it wasn't snowing, and now it is), so don't confuse it with the てくる of spatial movement.","grammar:2325:ex:words:0:zh":"snow","grammar:2325:ex:words:0:note":"ゆき","grammar:2325:ex:words:0:pos":"noun","grammar:2325:ex:words:1:zh":"(nominative)","grammar:2325:ex:words:1:pos":"particle","grammar:2325:ex:words:2:zh":"started to fall","grammar:2325:ex:words:2:note":"ふってきた","grammar:2325:ex:words:2:pos":"verb","grammar:2325:ex:points:0":"❗雪（ゆき）: snow; 雪が降る = to snow; 〜てくる = (an action) begins, gradually.","grammar:2325:ex:points:1":"雪: snow.","grammar:2325:ex2:trans":"I want to build a snowman.","grammar:2325:ex2:structure":"雪だるまを作りたい","grammar:2325:ex2:words:0:zh":"snowman","grammar:2325:ex2:words:0:note":"ゆきだるま","grammar:2325:ex2:words:0:pos":"noun","grammar:2325:ex2:words:1:zh":"(object marker)","grammar:2325:ex2:words:1:pos":"particle","grammar:2325:ex2:words:2:zh":"want to do","grammar:2325:ex2:words:2:note":"つくりたい","grammar:2325:ex2:words:2:pos":"verb","grammar:2325:ex2:points:0":"❗雪だるま: snowman (雪 + だるま = daruma doll).","grammar:2325:ex2:points:1":"雪だるま: snowman.","grammar:2325:ex3:trans":"Snow is beautiful.","grammar:2325:ex3:structure":"雪は美しい","grammar:2325:ex3:words:0:zh":"snow","grammar:2325:ex3:words:0:note":"ゆき","grammar:2325:ex3:words:0:pos":"noun","grammar:2325:ex3:words:1:zh":"(topic)","grammar:2325:ex3:words:1:pos":"particle","grammar:2325:ex3:words:2:zh":"beautiful","grammar:2325:ex3:words:2:note":"うつくしい","grammar:2325:ex3:words:2:pos":"adjective","grammar:2325:ex3:points:0":"❗美しい雪: beautiful snow.","grammar:2325:ex3:points:1":"美しい雪: beautiful snow.","grammar:2325:ex4:trans":"Snowy days are fun.","grammar:2325:ex4:structure":"雪の日は楽しい","grammar:2325:ex4:words:0:zh":"snow","grammar:2325:ex4:words:0:note":"ゆき","grammar:2325:ex4:words:0:pos":"noun","grammar:2325:ex4:words:1:zh":"'s","grammar:2325:ex4:words:1:pos":"particle","grammar:2325:ex4:words:2:zh":"day","grammar:2325:ex4:words:2:note":"ひ","grammar:2325:ex4:words:2:pos":"noun","grammar:2325:ex4:words:3:zh":"(topic)","grammar:2325:ex4:words:3:pos":"particle","grammar:2325:ex4:words:4:zh":"interesting","grammar:2325:ex4:words:4:note":"たのしい","grammar:2325:ex4:words:4:pos":"adjective","grammar:2325:ex4:points:0":"❗雪の日: a snowy day.","grammar:2325:ex4:points:1":"雪の日: a snowy day.","grammar:2325:ex5:trans":"I like walking on snow-covered roads.","grammar:2325:ex5:structure":"雪道を歩くのが好きだ","grammar:2325:ex5:words:0:zh":"snowy road","grammar:2325:ex5:words:0:note":"ゆきみち","grammar:2325:ex5:words:0:pos":"noun","grammar:2325:ex5:words:1:zh":"(path)","grammar:2325:ex5:words:1:pos":"particle","grammar:2325:ex5:words:2:zh":"walk","grammar:2325:ex5:words:2:note":"あるく","grammar:2325:ex5:words:2:pos":"verb","grammar:2325:ex5:words:3:zh":"(nominalizer)","grammar:2325:ex5:words:3:pos":"particle","grammar:2325:ex5:words:4:zh":"(object)","grammar:2325:ex5:words:4:pos":"particle","grammar:2325:ex5:words:5:zh":"to like","grammar:2325:ex5:words:5:note":"すき","grammar:2325:ex5:words:5:pos":"na-adjective","grammar:2325:ex5:words:6:zh":"is","grammar:2325:ex5:words:6:pos":"copula","grammar:2325:ex5:points:0":"❗雪道: a snow-covered road (雪 + 道); 道を歩く = to walk along a road.","grammar:2325:ex5:points:1":"雪道: a snowy road.","exam:2325:zh":"White snow is falling outside, and both the roads and roofs have turned white.","exam:2325:why":"What falls and turns the roads and roofs white is 「雪」. 「雨」 can also go with 「降る」, but it doesn't leave white snow on the ground."},"2326":{"example:2326:exzh":"I plan to go hunting.","example:2326:exzh2":"He is good at hunting.","example:2326:exzh3":"I hunted in the snow.","example:2326:exzh4":"Learn hunting techniques.","example:2326:exzh5":"The hunting season has begun."},"2327":{"example:2327:exzh":"He is a person of high status.","example:2327:exzh2":"You need to clarify your identity.","example:2327:exzh3":"She makes friends regardless of status.","example:2327:exzh4":"That status is important.","example:2327:exzh5":"Please show your ID."},"2328":{"example:2328:exzh":"Please let me off here.","example:2328:exzh2":"Give me a break!","example:2328:exzh3":"I beg for mercy.","example:2328:exzh4":"I can't tolerate his behavior, but I'll let him off.","example:2328:exzh5":"I'll let you off."},"2329":{"example:2329:exzh":"I'm grateful for your help.","example:2329:exzh2":"I feel grateful.","example:2329:exzh3":"Fortunately, I was helped out.","example:2329:exzh4":"I'm grateful for his support.","example:2329:exzh5":"I'm grateful for your kind words."},"2330":{"example:2330:exzh":"Civil servants work at the agency.","example:2330:exzh2":"This agency plays an important role.","example:2330:exzh3":"I need to go to the agency.","example:2330:exzh4":"Work at the agency is diverse.","example:2330:exzh5":"Let's follow the agency's rules."},"2331":{"example:2331:exzh":"He is a soccer player.","example:2331:exzh2":"The players are doing their best.","example:2331:exzh3":"The winning player received prize money.","example:2331:exzh4":"The players' practice is tough.","example:2331:exzh5":"I have a dream of becoming a player."},"2332":{"example:2332:exzh":"He returned safely.","example:2332:exzh2":"I'm just about to return.","example:2332:exzh3":"More and more people are returning to their country.","example:2332:exzh4":"The return plan has been announced.","example:2332:exzh5":"She is returning for the first time in several years."},"2333":{"example:2333:exzh":"We need a clear answer.","example:2333:exzh2":"He clearly stated his opinion.","example:2333:exzh3":"It's important to have clear goals.","example:2333:exzh4":"That explanation was clear.","example:2333:exzh5":"It's important to communicate clearly."},"2334":{"example:2334:exzh":"He's really a piece of trash.","example:2334:exzh2":"There's no need to deal with trash like that.","example:2334:exzh3":"Throw away the trash.","example:2334:exzh4":"Please don't say things that are like trash.","example:2334:exzh5":"He thinks he's a piece of trash."},"2335":{"example:2335:exzh":"Preparations have to be made before winter comes.","example:2335:exzh2":"Winter is cold, so please wear warm clothes.","example:2335:exzh3":"The stars in the winter night sky are beautiful.","example:2335:exzh4":"When winter comes, it snows.","example:2335:exzh5":"I look forward to winter every year.","grammar:2335:ex:trans":"You have to get ready before winter comes.","grammar:2335:ex:structure":"冬が来る前に準備をしなければならない","grammar:2335:ex:explain":"The pattern 「〜前に」 means \"before…\" and follows the plain form of a verb: 「冬が来る前に」 = before winter comes. 「準備をする」 = to prepare. The sentence-ending 「〜なければならない」 means \"must…, have to…\" and expresses obligation or necessity. The whole sentence = \"You have to get ready before winter comes.\" Key point: 「〜前に」 marks the order in time (before doing A), and 「〜なければならない」 is an important pattern for obligation.","grammar:2335:ex:words:0:zh":"winter","grammar:2335:ex:words:0:note":"ふゆ","grammar:2335:ex:words:0:pos":"noun","grammar:2335:ex:words:1:zh":"(nominative)","grammar:2335:ex:words:1:pos":"particle","grammar:2335:ex:words:2:zh":"come","grammar:2335:ex:words:2:note":"くる","grammar:2335:ex:words:2:pos":"verb","grammar:2335:ex:words:3:zh":"before","grammar:2335:ex:words:3:note":"まえ","grammar:2335:ex:words:3:pos":"noun","grammar:2335:ex:words:4:zh":"(point in time)","grammar:2335:ex:words:4:pos":"particle","grammar:2335:ex:words:5:zh":"prepare","grammar:2335:ex:words:5:note":"じゅんび","grammar:2335:ex:words:5:pos":"noun","grammar:2335:ex:words:6:zh":"(object marker)","grammar:2335:ex:words:6:pos":"particle","grammar:2335:ex:words:7:zh":"must do","grammar:2335:ex:words:7:pos":"verb","grammar:2335:ex:points:0":"❗冬（ふゆ）: winter; 〜前に = before…; 〜なければならない = must…","grammar:2335:ex:points:1":"冬: winter.","grammar:2335:ex2:trans":"Winter is cold, so please wear warm clothes.","grammar:2335:ex2:structure":"冬は寒いので、暖かい服を着てください","grammar:2335:ex2:words:0:zh":"winter","grammar:2335:ex2:words:0:note":"ふゆ","grammar:2335:ex2:words:0:pos":"noun","grammar:2335:ex2:words:1:zh":"(topic)","grammar:2335:ex2:words:1:pos":"particle","grammar:2335:ex2:words:2:zh":"cold","grammar:2335:ex2:words:2:note":"さむい","grammar:2335:ex2:words:2:pos":"adjective","grammar:2335:ex2:words:3:zh":"because","grammar:2335:ex2:words:3:pos":"particle","grammar:2335:ex2:words:4:zh":"Warm","grammar:2335:ex2:words:4:note":"あたたかい","grammar:2335:ex2:words:4:pos":"adjective","grammar:2335:ex2:words:5:zh":"clothes","grammar:2335:ex2:words:5:note":"ふく","grammar:2335:ex2:words:5:pos":"noun","grammar:2335:ex2:words:6:zh":"(object marker)","grammar:2335:ex2:words:6:pos":"particle","grammar:2335:ex2:words:7:zh":"wear","grammar:2335:ex2:words:7:note":"きて","grammar:2335:ex2:words:7:pos":"verb","grammar:2335:ex2:words:8:zh":"please","grammar:2335:ex2:words:8:pos":"auxiliary verb","grammar:2335:ex2:points:0":"❗冬は寒い: winter is cold; 暖かい服 = warm clothes.","grammar:2335:ex2:points:1":"冬は寒い: winter is cold.","grammar:2335:ex3:trans":"The stars are beautiful in the winter night sky.","grammar:2335:ex3:structure":"冬の夜空は星がきれいです","grammar:2335:ex3:words:0:zh":"winter","grammar:2335:ex3:words:0:note":"ふゆ","grammar:2335:ex3:words:0:pos":"noun","grammar:2335:ex3:words:1:zh":"'s","grammar:2335:ex3:words:1:pos":"particle","grammar:2335:ex3:words:2:zh":"night sky","grammar:2335:ex3:words:2:note":"よぞら","grammar:2335:ex3:words:2:pos":"noun","grammar:2335:ex3:words:3:zh":"(topic)","grammar:2335:ex3:words:3:pos":"particle","grammar:2335:ex3:words:4:zh":"star","grammar:2335:ex3:words:4:note":"ほし","grammar:2335:ex3:words:4:pos":"noun","grammar:2335:ex3:words:5:zh":"(nominative)","grammar:2335:ex3:words:5:pos":"particle","grammar:2335:ex3:words:6:zh":"beautiful","grammar:2335:ex3:words:6:pos":"na-adjective","grammar:2335:ex3:words:7:zh":"(polite form)","grammar:2335:ex3:words:7:pos":"copula","grammar:2335:ex3:points:0":"❗冬の夜空: the winter night sky; 星がきれい = the stars are beautiful.","grammar:2335:ex3:points:1":"冬の夜空: the winter night sky.","grammar:2335:ex4:trans":"Once winter comes, it snows.","grammar:2335:ex4:structure":"冬になると雪が降る","grammar:2335:ex4:words:0:zh":"winter","grammar:2335:ex4:words:0:note":"ふゆ","grammar:2335:ex4:words:0:pos":"noun","grammar:2335:ex4:words:1:zh":"(point in time)","grammar:2335:ex4:words:1:pos":"particle","grammar:2335:ex4:words:2:zh":"become","grammar:2335:ex4:words:2:pos":"verb","grammar:2335:ex4:words:3:zh":"(as soon as…)","grammar:2335:ex4:words:3:pos":"particle","grammar:2335:ex4:words:4:zh":"snow","grammar:2335:ex4:words:4:note":"ゆき","grammar:2335:ex4:words:4:pos":"noun","grammar:2335:ex4:words:5:zh":"(nominative)","grammar:2335:ex4:words:5:pos":"particle","grammar:2335:ex4:words:6:zh":"down","grammar:2335:ex4:words:6:note":"ふる","grammar:2335:ex4:words:6:pos":"verb","grammar:2335:ex4:points:0":"❗冬になると: once winter comes, …; 雪が降る = it snows.","grammar:2335:ex4:points:1":"冬になると: when winter comes.","grammar:2335:ex5:trans":"I look forward to winter every year.","grammar:2335:ex5:structure":"毎年冬を楽しみにしています","grammar:2335:ex5:words:0:zh":"every year","grammar:2335:ex5:words:0:note":"まいとし","grammar:2335:ex5:words:0:pos":"adverb","grammar:2335:ex5:words:1:zh":"winter","grammar:2335:ex5:words:1:note":"ふゆ","grammar:2335:ex5:words:1:pos":"noun","grammar:2335:ex5:words:2:zh":"(object marker)","grammar:2335:ex5:words:2:pos":"particle","grammar:2335:ex5:words:3:zh":"look forward to","grammar:2335:ex5:words:3:note":"たのしみに","grammar:2335:ex5:words:3:pos":"adverb","grammar:2335:ex5:words:4:zh":"is doing","grammar:2335:ex5:words:4:pos":"verb","grammar:2335:ex5:points:0":"❗〜を楽しみにする: to look forward to… (an idiom).","grammar:2335:ex5:points:1":"楽しみにする: to look forward to.","exam:2335:zh":"The season that comes after spring, summer, and autumn is winter.","exam:2335:why":"The four seasons go spring, summer, autumn, winter. Spring comes after winter, so it can't come directly after autumn."},"2336":{"example:2336:exzh":"She is a fashion model.","example:2336:exzh2":"The models in this video game are very realistic.","example:2336:exzh3":"We announced a new model.","example:2336:exzh4":"He works as a model.","example:2336:exzh5":"This model is popular."},"2337":{"example:2337:exzh":"That room is bright.","example:2337:exzh2":"He has a cheerful personality.","example:2337:exzh3":"I like bright colors.","example:2337:exzh4":"She always shows a cheerful smile.","example:2337:exzh5":"I believe in a bright future.","grammar:2337:ex:trans":"That room is bright.","grammar:2337:ex:structure":"〜は明るいです","grammar:2337:ex:explain":"「その部屋」 uses the pre-noun adjectival 「その」 = that room. In 「〜は明るいです」, 「明るい（あかるい）」 is the i-adjective bright (also extended to mean cheerful), the opposite of 「暗い」, and it takes 「です」 as a predicate. The whole sentence = that room is bright. Key point: 「この、その、あの」 are pre-noun adjectivals and must be followed by a noun; 「明るい／暗い」 are a pair of opposite i-adjectives.","grammar:2337:ex:words:0:zh":"that","grammar:2337:ex:words:0:pos":"pre-noun adjectival","grammar:2337:ex:words:1:zh":"room","grammar:2337:ex:words:1:note":"へや","grammar:2337:ex:words:1:pos":"noun","grammar:2337:ex:words:2:zh":"(topic)","grammar:2337:ex:words:2:pos":"particle","grammar:2337:ex:words:3:zh":"bright","grammar:2337:ex:words:3:note":"あかるい","grammar:2337:ex:words:3:pos":"adjective","grammar:2337:ex:words:4:zh":"(polite form)","grammar:2337:ex:words:4:pos":"copula","grammar:2337:ex:points:0":"❗明るい（あかるい）: bright; also extended to mean cheerful; vs 暗い (dark).","grammar:2337:ex:points:1":"明るい: bright.","grammar:2337:ex2:trans":"He has a cheerful personality.","grammar:2337:ex2:structure":"〜は明るい〜です","grammar:2337:ex2:words:0:zh":"he","grammar:2337:ex2:words:0:note":"かれ","grammar:2337:ex2:words:0:pos":"pronoun","grammar:2337:ex2:words:1:zh":"(topic)","grammar:2337:ex2:words:1:pos":"particle","grammar:2337:ex2:words:2:zh":"cheerful","grammar:2337:ex2:words:2:note":"あかるい","grammar:2337:ex2:words:2:pos":"adjective","grammar:2337:ex2:words:3:zh":"personality","grammar:2337:ex2:words:3:note":"せいかく","grammar:2337:ex2:words:3:pos":"noun","grammar:2337:ex2:words:4:zh":"is","grammar:2337:ex2:words:4:pos":"copula","grammar:2337:ex2:points:0":"❗明るい性格: a cheerful personality (an extended sense of 明るい); 性格 = personality.","grammar:2337:ex2:points:1":"明るい性格: cheerful.","grammar:2337:ex3:trans":"I like bright colors.","grammar:2337:ex3:structure":"明るい〜が好きです","grammar:2337:ex3:words:0:zh":"bright","grammar:2337:ex3:words:0:note":"あかるい","grammar:2337:ex3:words:0:pos":"adjective","grammar:2337:ex3:words:1:zh":"color","grammar:2337:ex3:words:1:note":"いろ","grammar:2337:ex3:words:1:pos":"noun","grammar:2337:ex3:words:2:zh":"(object)","grammar:2337:ex3:words:2:pos":"particle","grammar:2337:ex3:words:3:zh":"to like","grammar:2337:ex3:words:3:note":"すき","grammar:2337:ex3:words:3:pos":"na-adjective","grammar:2337:ex3:words:4:zh":"(polite form)","grammar:2337:ex3:words:4:pos":"copula","grammar:2337:ex3:points:0":"❗明るい色: a bright color, a light color.","grammar:2337:ex3:points:1":"明るい色: bright colors.","grammar:2337:ex4:trans":"She always shows a bright smile.","grammar:2337:ex4:structure":"明るい〜を見せる","grammar:2337:ex4:words:0:zh":"she","grammar:2337:ex4:words:0:note":"かのじょ","grammar:2337:ex4:words:0:pos":"pronoun","grammar:2337:ex4:words:1:zh":"(topic)","grammar:2337:ex4:words:1:pos":"particle","grammar:2337:ex4:words:2:zh":"always","grammar:2337:ex4:words:2:pos":"adverb","grammar:2337:ex4:words:3:zh":"clear","grammar:2337:ex4:words:3:note":"あかるい","grammar:2337:ex4:words:3:pos":"adjective","grammar:2337:ex4:words:4:zh":"Smile","grammar:2337:ex4:words:4:note":"えがお","grammar:2337:ex4:words:4:pos":"noun","grammar:2337:ex4:words:5:zh":"(object marker)","grammar:2337:ex4:words:5:pos":"particle","grammar:2337:ex4:words:6:zh":"to show","grammar:2337:ex4:words:6:note":"みせる","grammar:2337:ex4:words:6:pos":"verb","grammar:2337:ex4:points:0":"❗明るい笑顔: a radiant smile; 笑顔を見せる = to show a smile.","grammar:2337:ex4:points:1":"明るい笑顔: a radiant smile.","grammar:2337:ex5:trans":"I believe in a bright future.","grammar:2337:ex5:structure":"明るい〜を信じています","grammar:2337:ex5:words:0:zh":"bright","grammar:2337:ex5:words:0:note":"あかるい","grammar:2337:ex5:words:0:pos":"adjective","grammar:2337:ex5:words:1:zh":"the future","grammar:2337:ex5:words:1:note":"みらい","grammar:2337:ex5:words:1:pos":"noun","grammar:2337:ex5:words:2:zh":"(object marker)","grammar:2337:ex5:words:2:pos":"particle","grammar:2337:ex5:words:3:zh":"believe in","grammar:2337:ex5:words:3:note":"しんじています","grammar:2337:ex5:words:3:pos":"verb","grammar:2337:ex5:points:0":"❗明るい未来: a bright future (an extended sense of 明るい); 信じる = to believe.","grammar:2337:ex5:points:1":"明るい未来: a bright future.","exam:2337:zh":"This room has big windows, so it's bright during the day even without turning on the light.","exam:2337:why":"Big windows let in natural light, so it's 「明るい」 even without the light on. 「暗い」 means dark, the opposite of the daylight clue in the sentence."},"2338":{"example:2338:exzh":"The bottom of the box is torn.","example:2338:exzh2":"What is at the bottom of the sea?","example:2338:exzh3":"Please don't drop anything down to the bottom.","example:2338:exzh4":"The bottom of this pond is mud.","example:2338:exzh5":"Let's see what's at the bottom."},"2340":{"example:2340:exzh":"He is a junior soccer player.","example:2340:exzh2":"This tournament is for juniors.","example:2340:exzh3":"She teaches a junior class.","example:2340:exzh4":"I had all kinds of experiences back in my junior days.","example:2340:exzh5":"This junior team is very strong."},"2341":{"example:2341:exzh":"This room is ten feet high.","example:2341:exzh2":"The bridge is twenty feet long.","example:2341:exzh3":"He is six feet tall.","example:2341:exzh4":"Convert feet into meters.","example:2341:exzh5":"I measure distance in feet."},"2342":{"example:2342:exzh":"The enemy army has retreated.","example:2342:exzh2":"We are preparing to retreat.","example:2342:exzh3":"Sometimes retreating is important.","example:2342:exzh4":"That plan led to a retreat.","example:2342:exzh5":"He retreated after the war."},"2343":{"example:2343:exzh":"She says she'd rather stay home.","example:2343:exzh2":"I think that would be better instead.","example:2343:exzh3":"Rather, I'm in favor of that opinion.","example:2343:exzh4":"He said he'd rather not work.","example:2343:exzh5":"Rather, this is what's really needed."},"2344":{"example:2344:exzh":"I'm meeting a friend next week.","example:2344:exzh2":"Next week looks like it'll be busy.","example:2344:exzh3":"Please tell me your plans for next week.","example:2344:exzh4":"I'm going on a trip next week.","example:2344:exzh5":"There's a test next Monday.","grammar:2344:ex:trans":"I'll meet my friend next week.","grammar:2344:ex:structure":"来週、友達と会います","grammar:2344:ex:explain":"「来週（らいしゅう）」 is a time noun meaning next week, and it can go straight at the start of a sentence as an adverbial. In 「友達と会う」, 「と」 marks the partner in a shared action (with a friend), and 「会います」 is the polite form. Whole sentence = I'll meet a friend next week. Key point: in 「〜と会う」, 「と」 means \"together with someone\"; two-way actions like meeting and talking all take 「と」.","grammar:2344:ex:words:0:zh":"next week","grammar:2344:ex:words:0:note":"らいしゅう","grammar:2344:ex:words:0:pos":"noun","grammar:2344:ex:words:1:zh":"friend","grammar:2344:ex:words:1:note":"ともだち","grammar:2344:ex:words:1:pos":"noun","grammar:2344:ex:words:2:zh":"(object)","grammar:2344:ex:words:2:pos":"particle","grammar:2344:ex:words:3:zh":"meet","grammar:2344:ex:words:3:note":"あいます","grammar:2344:ex:words:3:pos":"verb","grammar:2344:ex:points:0":"❗来週（らいしゅう）: next week, the coming week (来 + 週).","grammar:2344:ex:points:1":"来週: next week.","grammar:2344:ex2:trans":"It looks like next week will be busy.","grammar:2344:ex2:structure":"来週は忙しくなりそうです","grammar:2344:ex2:words:0:zh":"next week","grammar:2344:ex2:words:0:note":"らいしゅう","grammar:2344:ex2:words:0:pos":"noun","grammar:2344:ex2:words:1:zh":"(topic)","grammar:2344:ex2:words:1:pos":"particle","grammar:2344:ex2:words:2:zh":"busy","grammar:2344:ex2:words:2:note":"いそがしく","grammar:2344:ex2:words:2:pos":"adjective","grammar:2344:ex2:words:3:zh":"looks like it will become","grammar:2344:ex2:words:3:note":"なりそう","grammar:2344:ex2:words:3:pos":"verb","grammar:2344:ex2:words:4:zh":"(polite form)","grammar:2344:ex2:words:4:pos":"copula","grammar:2344:ex2:points:0":"❗〜そうだ: looks like it's going to…; 忙しくなる = to get busy.","grammar:2344:ex2:points:1":"なりそう: looks like it will.","grammar:2344:ex3:trans":"Please tell me next week's schedule.","grammar:2344:ex3:structure":"来週の予定を教えてください","grammar:2344:ex3:words:0:zh":"next week","grammar:2344:ex3:words:0:note":"らいしゅう","grammar:2344:ex3:words:0:pos":"noun","grammar:2344:ex3:words:1:zh":"'s","grammar:2344:ex3:words:1:pos":"particle","grammar:2344:ex3:words:2:zh":"plan","grammar:2344:ex3:words:2:note":"よてい","grammar:2344:ex3:words:2:pos":"noun","grammar:2344:ex3:words:3:zh":"(object marker)","grammar:2344:ex3:words:3:pos":"particle","grammar:2344:ex3:words:4:zh":"tell","grammar:2344:ex3:words:4:note":"おしえて","grammar:2344:ex3:words:4:pos":"verb","grammar:2344:ex3:words:5:zh":"please","grammar:2344:ex3:words:5:pos":"auxiliary verb","grammar:2344:ex3:points:0":"❗来週の予定: next week's plans.","grammar:2344:ex3:points:1":"来週の予定: next week's schedule.","grammar:2344:ex4:trans":"I'm going on a trip next week.","grammar:2344:ex4:structure":"来週、旅行に行きます","grammar:2344:ex4:words:0:zh":"next week","grammar:2344:ex4:words:0:note":"らいしゅう","grammar:2344:ex4:words:0:pos":"noun","grammar:2344:ex4:words:1:zh":"travel / trip","grammar:2344:ex4:words:1:note":"りょこう","grammar:2344:ex4:words:1:pos":"noun","grammar:2344:ex4:words:2:zh":"(purpose)","grammar:2344:ex4:words:2:pos":"particle","grammar:2344:ex4:words:3:zh":"go","grammar:2344:ex4:words:3:note":"いきます","grammar:2344:ex4:words:3:pos":"verb","grammar:2344:ex4:points:0":"❗来週旅行に行く: to go on a trip next week.","grammar:2344:ex4:points:1":"旅行に行く: to go on a trip.","grammar:2344:ex5:trans":"There's a test next Monday.","grammar:2344:ex5:structure":"来週の月曜日にテストがあります","grammar:2344:ex5:words:0:zh":"next week","grammar:2344:ex5:words:0:note":"らいしゅう","grammar:2344:ex5:words:0:pos":"noun","grammar:2344:ex5:words:1:zh":"'s","grammar:2344:ex5:words:1:pos":"particle","grammar:2344:ex5:words:2:zh":"Monday","grammar:2344:ex5:words:2:note":"げつようび","grammar:2344:ex5:words:2:pos":"noun","grammar:2344:ex5:words:3:zh":"(point in time)","grammar:2344:ex5:words:3:pos":"particle","grammar:2344:ex5:words:4:zh":"test","grammar:2344:ex5:words:4:note":"loanword","grammar:2344:ex5:words:4:pos":"noun","grammar:2344:ex5:words:5:zh":"(nominative)","grammar:2344:ex5:words:5:pos":"particle","grammar:2344:ex5:words:6:zh":"there is / are","grammar:2344:ex5:words:6:pos":"verb","grammar:2344:ex5:points:0":"❗来週の月曜日: next Monday.","grammar:2344:ex5:points:1":"来週の月曜日: next Monday.","exam:2344:zh":"Today is Monday, so the Monday seven days from now is next week's Monday.","exam:2344:why":"Seven days later is the same day of the following week, so the answer is next week. The week after next means two weeks later, and the same day would be fourteen days apart."},"2345":{"example:2345:exzh":"She has a diamond ring.","example:2345:exzh2":"Diamonds are very expensive.","example:2345:exzh3":"I like the diamond design.","example:2345:exzh4":"This diamond is very beautiful.","example:2345:exzh5":"I'm going to buy jewelry made with diamonds."},"2346":{"example:2346:exzh":"Give me that snack.","example:2346:exzh2":"Give me more water.","example:2346:exzh3":"Can I have this?","example:2346:exzh4":"Give it to me, please, help me.","example:2346:exzh5":"Give me that information."},"2347":{"example:2347:exzh":"He swims every day.","example:2347:exzh2":"Swimming is a lot of fun.","example:2347:exzh3":"I'm planning to go swimming in summer.","example:2347:exzh4":"Some people can't swim.","example:2347:exzh5":"I'm swimming in the swim meet.","grammar:2347:ex:trans":"He swims every day.","grammar:2347:ex:structure":"〜は毎日泳ぎます","grammar:2347:ex:explain":"「毎日」 is the adverb meaning every day, showing frequency. 「泳ぐ（およぐ）」 is the intransitive verb meaning to swim, and 「泳ぎます」 is its polite form (ぐ→ぎます). 「彼は」 is the topic. The whole sentence means he swims every day. Key point: for a godan (u-) verb, the masu-form changes the final u-row sound to the i-row (泳ぐ→泳ぎ＋ます); frequency adverbs like 「毎日」 go directly before the verb.","grammar:2347:ex:words:0:zh":"he","grammar:2347:ex:words:0:note":"かれ","grammar:2347:ex:words:0:pos":"pronoun","grammar:2347:ex:words:1:zh":"(topic)","grammar:2347:ex:words:1:pos":"particle","grammar:2347:ex:words:2:zh":"every day","grammar:2347:ex:words:2:note":"まいにち","grammar:2347:ex:words:2:pos":"adverb","grammar:2347:ex:words:3:zh":"to swim","grammar:2347:ex:words:3:note":"およぎます","grammar:2347:ex:words:3:pos":"verb","grammar:2347:ex:points:0":"泳ぐ（およぐ）: to swim.","grammar:2347:ex:points:1":"毎日泳ぐ: to swim every day.","grammar:2347:ex2:trans":"Swimming is a lot of fun.","grammar:2347:ex2:structure":"〜ことは楽しいです","grammar:2347:ex2:words:0:zh":"to swim","grammar:2347:ex2:words:0:note":"およぐ","grammar:2347:ex2:words:0:pos":"verb","grammar:2347:ex2:words:1:zh":"(nominalizer)","grammar:2347:ex2:words:1:pos":"noun","grammar:2347:ex2:words:2:zh":"(topic)","grammar:2347:ex2:words:2:pos":"particle","grammar:2347:ex2:words:3:zh":"extremely","grammar:2347:ex2:words:3:pos":"adverb","grammar:2347:ex2:words:4:zh":"interesting","grammar:2347:ex2:words:4:note":"たのしい","grammar:2347:ex2:words:4:pos":"adjective","grammar:2347:ex2:words:5:zh":"(polite form)","grammar:2347:ex2:words:5:pos":"copula","grammar:2347:ex2:points:0":"泳ぐこと: swimming (nominalized).","grammar:2347:ex2:points:1":"〜ことは楽しい: doing … is fun.","grammar:2347:ex3:trans":"I plan to go swimming in the summer.","grammar:2347:ex3:structure":"泳ぎに行く予定です","grammar:2347:ex3:words:0:zh":"summer","grammar:2347:ex3:words:0:note":"なつ","grammar:2347:ex3:words:0:pos":"noun","grammar:2347:ex3:words:1:zh":"(point in time)","grammar:2347:ex3:words:1:pos":"particle","grammar:2347:ex3:words:2:zh":"to swim","grammar:2347:ex3:words:2:note":"およぎ","grammar:2347:ex3:words:2:pos":"noun","grammar:2347:ex3:words:3:zh":"(purpose)","grammar:2347:ex3:words:3:pos":"particle","grammar:2347:ex3:words:4:zh":"go","grammar:2347:ex3:words:4:note":"いく","grammar:2347:ex3:words:4:pos":"verb","grammar:2347:ex3:words:5:zh":"plan","grammar:2347:ex3:words:5:note":"よてい","grammar:2347:ex3:words:5:pos":"noun","grammar:2347:ex3:words:6:zh":"(polite form)","grammar:2347:ex3:words:6:pos":"copula","grammar:2347:ex3:points:0":"❗泳ぎに行く: to go swimming (the masu-stem of 泳ぐ + に).","grammar:2347:ex3:points:1":"〜予定です: is scheduled to…","grammar:2347:ex4:trans":"Some people can't swim.","grammar:2347:ex4:structure":"泳げない人もいます","grammar:2347:ex4:words:0:zh":"can't swim","grammar:2347:ex4:words:0:note":"およげない","grammar:2347:ex4:words:0:pos":"verb","grammar:2347:ex4:words:1:zh":"person","grammar:2347:ex4:words:1:note":"ひと","grammar:2347:ex4:words:1:pos":"noun","grammar:2347:ex4:words:2:zh":"also, too","grammar:2347:ex4:words:2:pos":"particle","grammar:2347:ex4:words:3:zh":"there is / are","grammar:2347:ex4:words:3:pos":"verb","grammar:2347:ex4:points:0":"❗泳げない: can't swim (the negative potential of 泳げる).","grammar:2347:ex4:points:1":"〜人もいる: there are also people who…","grammar:2347:ex5:trans":"I'll swim in the swimming competition.","grammar:2347:ex5:structure":"〜大会で泳ぎます","grammar:2347:ex5:explain":"「水泳大会」 is made up of 「水泳」 and 「大会」 and means a swimming competition. 「で」 marks the occasion where the swimming takes place. 「泳ぎます」 is the polite non-past form of 「泳ぐ」, and in this sentence it expresses the plan to swim in the competition.","grammar:2347:ex5:words:0:zh":"to swim","grammar:2347:ex5:words:0:note":"すいえい","grammar:2347:ex5:words:0:pos":"noun","grammar:2347:ex5:words:1:zh":"competition, meet","grammar:2347:ex5:words:1:note":"たいかい","grammar:2347:ex5:words:1:pos":"noun","grammar:2347:ex5:words:2:zh":"(the occasion where the action takes place)","grammar:2347:ex5:words:2:pos":"particle","grammar:2347:ex5:words:3:zh":"to swim","grammar:2347:ex5:words:3:note":"およぎ","grammar:2347:ex5:words:3:pos":"verb","grammar:2347:ex5:words:4:zh":"(polite ending)","grammar:2347:ex5:words:4:pos":"auxiliary verb","grammar:2347:ex5:points:0":"Besides marking the place of an action, 「で」 can also mark the occasion of an event such as a competition.","grammar:2347:ex5:points:1":"When 「泳ぐ」 takes 「ます」, it becomes 「泳ぎます」.","exam:2347:zh":"To swim well in the school pool, I'm practicing how to move my hands and feet in the water.","exam:2347:why":"Practicing coordinated hand and foot movement in a pool is for 「泳ぐ」. 「走る」 means running, which doesn't fit moving through water."},"2348":{"example:2348:exzh":"I live in Tokyo.","example:2348:exzh2":"Tokyo is a big city.","example:2348:exzh3":"I'm going to Tokyo next week.","example:2348:exzh4":"Tokyo has lots of sightseeing spots.","example:2348:exzh5":"The trains in Tokyo are very convenient.","grammar:2348:ex:trans":"I live in Tokyo.","grammar:2348:ex:structure":"私は東京に住んでいます","grammar:2348:ex:explain":"In 「東京に住む」, 「に」 marks the place where you live. 「住んでいます」 uses 「〜ている」 to show the continuing state of living there (you have been living there all along) — verbs like 住む take ている for a long-term state, not \"in the middle of moving in.\" 「私は」 is the topic. Whole sentence = I live in Tokyo. Key point: 「〜に住んでいる」 is the fixed way to say where you live: 「に」 for the place, 「ている」 for the state.","grammar:2348:ex:words:0:zh":"I","grammar:2348:ex:words:0:note":"わたし","grammar:2348:ex:words:0:pos":"pronoun","grammar:2348:ex:words:1:zh":"(topic)","grammar:2348:ex:words:1:pos":"particle","grammar:2348:ex:words:2:zh":"Tokyo","grammar:2348:ex:words:2:note":"とうきょう","grammar:2348:ex:words:2:pos":"noun","grammar:2348:ex:words:3:zh":"(location of existence)","grammar:2348:ex:words:3:pos":"particle","grammar:2348:ex:words:4:zh":"live (there)","grammar:2348:ex:words:4:note":"すんでいます","grammar:2348:ex:words:4:pos":"verb","grammar:2348:ex:points:0":"❗東京（とうきょう）: Tokyo (the capital of Japan).","grammar:2348:ex:points:1":"東京: Tokyo.","grammar:2348:ex2:trans":"Tokyo is a big city.","grammar:2348:ex2:structure":"東京は大きな都市です","grammar:2348:ex2:words:0:zh":"Tokyo","grammar:2348:ex2:words:0:note":"とうきょう","grammar:2348:ex2:words:0:pos":"noun","grammar:2348:ex2:words:1:zh":"(topic)","grammar:2348:ex2:words:1:pos":"particle","grammar:2348:ex2:words:2:zh":"big","grammar:2348:ex2:words:2:note":"おおきな","grammar:2348:ex2:words:2:pos":"pre-noun adjectival","grammar:2348:ex2:words:3:zh":"city","grammar:2348:ex2:words:3:note":"とし","grammar:2348:ex2:words:3:pos":"noun","grammar:2348:ex2:words:4:zh":"is","grammar:2348:ex2:words:4:pos":"copula","grammar:2348:ex2:points:0":"❗大きな都市: a big city.","grammar:2348:ex2:points:1":"大きな都市: a large city.","grammar:2348:ex3:trans":"I'm going to Tokyo next week.","grammar:2348:ex3:structure":"来週東京に行きます","grammar:2348:ex3:words:0:zh":"next week","grammar:2348:ex3:words:0:note":"らいしゅう","grammar:2348:ex3:words:0:pos":"noun","grammar:2348:ex3:words:1:zh":"Tokyo","grammar:2348:ex3:words:1:note":"とうきょう","grammar:2348:ex3:words:1:pos":"noun","grammar:2348:ex3:words:2:zh":"(destination)","grammar:2348:ex3:words:2:pos":"particle","grammar:2348:ex3:words:3:zh":"go","grammar:2348:ex3:words:3:note":"いきます","grammar:2348:ex3:words:3:pos":"verb","grammar:2348:ex3:points:0":"❗東京に行く: to go to Tokyo.","grammar:2348:ex3:points:1":"東京に行く: go to Tokyo.","grammar:2348:ex4:trans":"Tokyo has many sightseeing spots.","grammar:2348:ex4:structure":"東京にはたくさんの観光地があります","grammar:2348:ex4:words:0:zh":"Tokyo","grammar:2348:ex4:words:0:note":"とうきょう","grammar:2348:ex4:words:0:pos":"noun","grammar:2348:ex4:words:1:zh":"(location of existence)","grammar:2348:ex4:words:1:pos":"particle","grammar:2348:ex4:words:2:zh":"(contrast)","grammar:2348:ex4:words:2:pos":"particle","grammar:2348:ex4:words:3:zh":"a lot","grammar:2348:ex4:words:3:pos":"adverb","grammar:2348:ex4:words:4:zh":"'s","grammar:2348:ex4:words:4:pos":"particle","grammar:2348:ex4:words:5:zh":"tourist attractions","grammar:2348:ex4:words:5:note":"かんこうち","grammar:2348:ex4:words:5:pos":"noun","grammar:2348:ex4:words:6:zh":"(nominative)","grammar:2348:ex4:words:6:pos":"particle","grammar:2348:ex4:words:7:zh":"there is / are","grammar:2348:ex4:words:7:pos":"verb","grammar:2348:ex4:points:0":"❗観光地: sightseeing spot; 東京には = in Tokyo there are…","grammar:2348:ex4:points:1":"観光地: sightseeing spot.","grammar:2348:ex5:trans":"Trains in Tokyo are convenient.","grammar:2348:ex5:structure":"東京の電車は便利です","grammar:2348:ex5:words:0:zh":"Tokyo","grammar:2348:ex5:words:0:note":"とうきょう","grammar:2348:ex5:words:0:pos":"noun","grammar:2348:ex5:words:1:zh":"'s","grammar:2348:ex5:words:1:pos":"particle","grammar:2348:ex5:words:2:zh":"train","grammar:2348:ex5:words:2:note":"でんしゃ","grammar:2348:ex5:words:2:pos":"noun","grammar:2348:ex5:words:3:zh":"(topic)","grammar:2348:ex5:words:3:pos":"particle","grammar:2348:ex5:words:4:zh":"convenient","grammar:2348:ex5:words:4:note":"べんり","grammar:2348:ex5:words:4:pos":"na-adjective","grammar:2348:ex5:words:5:zh":"(polite form)","grammar:2348:ex5:words:5:pos":"copula","grammar:2348:ex5:points:0":"❗東京の電車: Tokyo trains; 便利 = convenient.","grammar:2348:ex5:points:1":"東京の電車: Tokyo's trains.","exam:2348:zh":"The capital of Japan is Tokyo.","exam:2348:why":"Tokyo is the capital of Japan. Kyoto is also a city in Japan, but it is not the capital referred to in this sentence."},"2349":{"example:2349:exzh":"That country is the United States.","example:2349:exzh2":"Do you know the principles of the United States?","example:2349:exzh3":"The culture of the United States is diverse.","example:2349:exzh4":"Learning the history of the United States is interesting.","example:2349:exzh5":"Discuss the legal system of the United States."},"2350":{"example:2350:exzh":"They started fighting over land.","example:2350:exzh2":"I hated watching a fight between brothers.","example:2350:exzh3":"I think fighting is pointless.","example:2350:exzh4":"Let's talk it out so we can avoid a fight.","example:2350:exzh5":"Conflict in society is a problem."},"2351":{"example:2351:exzh":"I heard the latest report on the news.","example:2351:exzh2":"There's more and more coverage about that incident.","example:2351:exzh3":"I'm checking whether the report is true.","example:2351:exzh4":"You need to be careful about media reports.","example:2351:exzh5":"The credibility of the report is being questioned."},"2352":{"example:2352:exzh":"He is a major in the army.","example:2352:exzh2":"The unit moved under the major's command.","example:2352:exzh3":"The major is well versed in strategy.","example:2352:exzh4":"The major trains the soldiers well.","example:2352:exzh5":"He carried out the mission as a major."},"2353":{"example:2353:exzh":"Thank you for accepting my offer.","example:2353:exzh2":"I was surprised by his offer.","example:2353:exzh3":"It takes courage to make an offer.","example:2353:exzh4":"If you have any proposal, please don't hesitate to tell me.","example:2353:exzh5":"She made an offer for a new project."},"2354":{"example:2354:exzh":"He received payment for his work.","example:2354:exzh2":"High pay is attractive.","example:2354:exzh3":"We talked about the pay.","example:2354:exzh4":"Many people are looking for a reward.","example:2354:exzh5":"A reward becomes motivation for work."},"2355":{"example:2355:exzh":"Please give the signal.","example:2355:exzh2":"He's waiting for the signal.","example:2355:exzh3":"The signal is important.","example:2355:exzh4":"We missed the signal.","example:2355:exzh5":"Understanding the signal is important."},"2357":{"example:2357:exzh":"Japanese festivals are a lot of fun.","example:2357:exzh2":"There are many festivals in autumn.","example:2357:exzh3":"Fireworks go up during festivals.","example:2357:exzh4":"I'll join the local festival.","example:2357:exzh5":"The preparations for the festival are busy.","grammar:2357:ex:trans":"Japanese festivals are a lot of fun.","grammar:2357:ex:structure":"日本のお祭りはとても楽しいです","grammar:2357:ex:explain":"「日本のお祭り」 uses 「の」 = Japanese festivals; 「祭り（まつり）」 refers to traditional festivals and shrine fairs, and adding 「お」 makes it more polite (お祭り). In 「〜はとても楽しいです」, 「楽しい」 is an i-adjective serving as the predicate. The whole sentence = Japanese festivals are a lot of fun. Key point: 「お」 is a beautifying, polite prefix (お祭り, お茶, お金) that makes the tone softer and more refined.","grammar:2357:ex:words:0:zh":"Japan","grammar:2357:ex:words:0:note":"にほん","grammar:2357:ex:words:0:pos":"noun","grammar:2357:ex:words:1:zh":"'s","grammar:2357:ex:words:1:pos":"particle","grammar:2357:ex:words:2:zh":"festival","grammar:2357:ex:words:2:note":"おまつり","grammar:2357:ex:words:2:pos":"noun","grammar:2357:ex:words:3:zh":"(topic)","grammar:2357:ex:words:3:pos":"particle","grammar:2357:ex:words:4:zh":"extremely","grammar:2357:ex:words:4:pos":"adverb","grammar:2357:ex:words:5:zh":"interesting","grammar:2357:ex:words:5:note":"たのしい","grammar:2357:ex:words:5:pos":"adjective","grammar:2357:ex:words:6:zh":"(polite form)","grammar:2357:ex:words:6:pos":"copula","grammar:2357:ex:points:0":"❗祭り（まつり）: festival, shrine fair, celebration (a traditional festival of a shrine or local area); adding 「お」 makes it more polite (お祭り).","grammar:2357:ex:points:1":"祭り: festival / celebration (お祭り).","grammar:2357:ex2:trans":"There are many festivals in autumn.","grammar:2357:ex2:structure":"秋には多くの祭りがあります","grammar:2357:ex2:words:0:zh":"autumn","grammar:2357:ex2:words:0:note":"あき","grammar:2357:ex2:words:0:pos":"noun","grammar:2357:ex2:words:1:zh":"(time)","grammar:2357:ex2:words:1:pos":"particle","grammar:2357:ex2:words:2:zh":"a lot","grammar:2357:ex2:words:2:note":"おおく","grammar:2357:ex2:words:2:pos":"noun","grammar:2357:ex2:words:3:zh":"'s","grammar:2357:ex2:words:3:pos":"particle","grammar:2357:ex2:words:4:zh":"festival","grammar:2357:ex2:words:4:note":"まつり","grammar:2357:ex2:words:4:pos":"noun","grammar:2357:ex2:words:5:zh":"(nominative)","grammar:2357:ex2:words:5:pos":"particle","grammar:2357:ex2:words:6:zh":"there is / are","grammar:2357:ex2:words:6:pos":"verb","grammar:2357:ex2:points:0":"❗多くの祭り: many festivals.","grammar:2357:ex2:points:1":"多くの祭り: many festivals.","grammar:2357:ex3:trans":"Fireworks go up during the festival.","grammar:2357:ex3:structure":"お祭りの時は花火が上がります","grammar:2357:ex3:words:0:zh":"festival","grammar:2357:ex3:words:0:note":"おまつり","grammar:2357:ex3:words:0:pos":"noun","grammar:2357:ex3:words:1:zh":"'s","grammar:2357:ex3:words:1:pos":"particle","grammar:2357:ex3:words:2:zh":"time","grammar:2357:ex3:words:2:note":"とき","grammar:2357:ex3:words:2:pos":"noun","grammar:2357:ex3:words:3:zh":"(contrast)","grammar:2357:ex3:words:3:pos":"particle","grammar:2357:ex3:words:4:zh":"fireworks","grammar:2357:ex3:words:4:note":"はなび","grammar:2357:ex3:words:4:pos":"noun","grammar:2357:ex3:words:5:zh":"(nominative)","grammar:2357:ex3:words:5:pos":"particle","grammar:2357:ex3:words:6:zh":"to go up","grammar:2357:ex3:words:6:note":"あがります","grammar:2357:ex3:words:6:pos":"verb","grammar:2357:ex3:points:0":"❗花火が上がる: fireworks go up.","grammar:2357:ex3:points:1":"花火が上がる: fireworks go up.","grammar:2357:ex4:trans":"I'll take part in the local festival.","grammar:2357:ex4:structure":"地域の祭りに参加します","grammar:2357:ex4:words:0:zh":"local","grammar:2357:ex4:words:0:note":"ちいき","grammar:2357:ex4:words:0:pos":"noun","grammar:2357:ex4:words:1:zh":"'s","grammar:2357:ex4:words:1:pos":"particle","grammar:2357:ex4:words:2:zh":"festival","grammar:2357:ex4:words:2:note":"まつり","grammar:2357:ex4:words:2:pos":"noun","grammar:2357:ex4:words:3:zh":"(object)","grammar:2357:ex4:words:3:pos":"particle","grammar:2357:ex4:words:4:zh":"join","grammar:2357:ex4:words:4:note":"さんかします","grammar:2357:ex4:words:4:pos":"verb","grammar:2357:ex4:points:0":"❗祭りに参加: to take part in a festival.","grammar:2357:ex4:points:1":"祭りに参加: to take part in a festival.","grammar:2357:ex5:trans":"Preparations for the festival are hectic.","grammar:2357:ex5:structure":"お祭りの準備が忙しいです","grammar:2357:ex5:words:0:zh":"festival","grammar:2357:ex5:words:0:note":"おまつり","grammar:2357:ex5:words:0:pos":"noun","grammar:2357:ex5:words:1:zh":"'s","grammar:2357:ex5:words:1:pos":"particle","grammar:2357:ex5:words:2:zh":"prepare","grammar:2357:ex5:words:2:note":"じゅんび","grammar:2357:ex5:words:2:pos":"noun","grammar:2357:ex5:words:3:zh":"(nominative)","grammar:2357:ex5:words:3:pos":"particle","grammar:2357:ex5:words:4:zh":"busy","grammar:2357:ex5:words:4:note":"いそがしい","grammar:2357:ex5:words:4:pos":"adjective","grammar:2357:ex5:words:5:zh":"(polite form)","grammar:2357:ex5:words:5:pos":"copula","grammar:2357:ex5:points:0":"❗お祭りの準備: preparing for the festival.","grammar:2357:ex5:points:1":"お祭りの準備: preparing for the festival."},"2358":{"example:2358:exzh":"The money is gone.","example:2358:exzh2":"The food ran out, so I'm going to buy some.","example:2358:exzh3":"His memory soon disappeared.","example:2358:exzh4":"Time is running out.","example:2358:exzh5":"Hope hasn't disappeared yet.","grammar:2358:ex:trans":"The money is gone.","grammar:2358:ex:structure":"〜が無くなってしまった","grammar:2358:ex:explain":"「無くなる（なくなる）」 is an intransitive verb meaning that something disappears or runs out on its own, and its subject takes 「が」: 「お金が無くなる」 = the money is gone. The ending 「〜てしまう」 = ended up … (with regret), so 「無くなってしまった」 carries a tone of frustration and helplessness. The whole sentence = the money is gone. Key points: the intransitive 「無くなる」 (to disappear) versus the transitive 「無くす」 (to lose something); 「〜てしまう」 expresses regret.","grammar:2358:ex:words:0:zh":"money","grammar:2358:ex:words:0:note":"おかね","grammar:2358:ex:words:0:pos":"noun","grammar:2358:ex:words:1:zh":"(nominative)","grammar:2358:ex:words:1:pos":"particle","grammar:2358:ex:words:2:zh":"disappear","grammar:2358:ex:words:2:note":"なくなって","grammar:2358:ex:words:2:pos":"verb","grammar:2358:ex:words:3:zh":"(with regret)","grammar:2358:ex:words:3:pos":"auxiliary verb","grammar:2358:ex:points:0":"❗無くなる（なくなる）: (of things) to disappear, to run out, to be gone (intransitive verb); 〜てしまう = (regrettably) ended up …","grammar:2358:ex:points:1":"お金が無くなる: the money runs out.","grammar:2358:ex2:trans":"The food has run out, so I'm going to buy some.","grammar:2358:ex2:structure":"〜が無くなったから〜に行きます","grammar:2358:ex2:words:0:zh":"food","grammar:2358:ex2:words:0:note":"たべもの","grammar:2358:ex2:words:0:pos":"noun","grammar:2358:ex2:words:1:zh":"(nominative)","grammar:2358:ex2:words:1:pos":"particle","grammar:2358:ex2:words:2:zh":"ran out","grammar:2358:ex2:words:2:note":"なくなった","grammar:2358:ex2:words:2:pos":"verb","grammar:2358:ex2:words:3:zh":"because","grammar:2358:ex2:words:3:pos":"particle","grammar:2358:ex2:words:4:zh":"buy","grammar:2358:ex2:words:4:note":"かい","grammar:2358:ex2:words:4:pos":"noun","grammar:2358:ex2:words:5:zh":"(purpose)","grammar:2358:ex2:words:5:pos":"particle","grammar:2358:ex2:words:6:zh":"go","grammar:2358:ex2:words:6:pos":"verb","grammar:2358:ex2:points:0":"❗〜から: because …; 食べ物が無くなる = the food runs out; 買いに行く = to go buy.","grammar:2358:ex2:points:1":"無くなる: to run out.","grammar:2358:ex3:trans":"His memory quickly faded away.","grammar:2358:ex3:structure":"〜はすぐに無くなった","grammar:2358:ex3:words:0:zh":"he","grammar:2358:ex3:words:0:note":"かれ","grammar:2358:ex3:words:0:pos":"pronoun","grammar:2358:ex3:words:1:zh":"'s","grammar:2358:ex3:words:1:pos":"particle","grammar:2358:ex3:words:2:zh":"memory","grammar:2358:ex3:words:2:note":"きおく","grammar:2358:ex3:words:2:pos":"noun","grammar:2358:ex3:words:3:zh":"(topic)","grammar:2358:ex3:words:3:pos":"particle","grammar:2358:ex3:words:4:zh":"right away","grammar:2358:ex3:words:4:pos":"adverb","grammar:2358:ex3:words:5:zh":"Disappeared","grammar:2358:ex3:words:5:note":"なくなった","grammar:2358:ex3:words:5:pos":"verb","grammar:2358:ex3:points:0":"❗記憶が無くなる: memories vanish; 記憶 = memory.","grammar:2358:ex3:points:1":"記憶が無くなる: losing one's memory.","grammar:2358:ex4:trans":"Time is running short.","grammar:2358:ex4:structure":"〜が無くなってきました","grammar:2358:ex4:words:0:zh":"time","grammar:2358:ex4:words:0:note":"じかん","grammar:2358:ex4:words:0:pos":"noun","grammar:2358:ex4:words:1:zh":"(nominative)","grammar:2358:ex4:words:1:pos":"particle","grammar:2358:ex4:words:2:zh":"gradually running out","grammar:2358:ex4:words:2:note":"なくなってきました","grammar:2358:ex4:words:2:pos":"verb","grammar:2358:ex4:points:0":"❗〜てきた: to gradually start …; 時間が無くなる = time is running out.","grammar:2358:ex4:points:1":"時間が無くなる: to run out of time.","grammar:2358:ex5:trans":"Hope hasn't disappeared yet.","grammar:2358:ex5:structure":"〜は無くなっていない","grammar:2358:ex5:words:0:zh":"hope","grammar:2358:ex5:words:0:note":"きぼう","grammar:2358:ex5:words:0:pos":"noun","grammar:2358:ex5:words:1:zh":"(topic)","grammar:2358:ex5:words:1:pos":"particle","grammar:2358:ex5:words:2:zh":"hasn't disappeared yet","grammar:2358:ex5:words:2:note":"なくなっていない","grammar:2358:ex5:words:2:pos":"verb","grammar:2358:ex5:points:0":"❗無くなっていない: hasn't disappeared yet (〜ていない = has not yet …); 希望 = hope.","grammar:2358:ex5:points:1":"希望は無くならない: hope remains."},"2359":{"example:2359:exzh":"I got some advice from a friend.","example:2359:exzh2":"That advice was really helpful.","example:2359:exzh3":"Please don't ignore advice.","example:2359:exzh4":"I'll take his advice.","example:2359:exzh5":"It's important to listen to advice."},"2360":{"example:2360:exzh":"I was quarantined because of illness.","example:2360:exzh2":"Quarantine rules are needed.","example:2360:exzh3":"Life in quarantine is tough.","example:2360:exzh4":"Once quarantine is over, you can go outside.","example:2360:exzh5":"They're in an isolated environment."},"2361":{"example:2361:exzh":"He has been dispatched to the company.","example:2361:exzh2":"I work as a temporary worker.","example:2361:exzh3":"Temp work is varied.","example:2361:exzh4":"A new work assignment has been decided.","example:2361:exzh5":"Temp work is rewarding."},"2362":{"example:2362:exzh":"This item is 1,000 yen.","example:2362:exzh2":"I have 500 yen.","example:2362:exzh3":"I want to exchange yen.","example:2362:exzh4":"I went to a 100-yen shop.","example:2362:exzh5":"Japan's currency is the yen.","grammar:2362:ex:trans":"This product is 1,000 yen.","grammar:2362:ex:structure":"この商品は千円です","grammar:2362:ex:explain":"「円（えん）」 is the Japanese currency unit, and 「千円」= 1,000 yen. Note that the same character, read 「まる」, means a circle, while here it is read 「えん」 and means money. 「この商品は…です」 is a sentence of identification. Whole sentence = This product is 1,000 yen. Key point: use 「〜円（えん）」 for amounts of money; the same kanji 「円」 has different readings and meanings: 「えん」(yen) and 「まる」(circle).","grammar:2362:ex:words:0:zh":"this","grammar:2362:ex:words:0:pos":"pre-noun adjectival","grammar:2362:ex:words:1:zh":"product","grammar:2362:ex:words:1:note":"しょうひん","grammar:2362:ex:words:1:pos":"noun","grammar:2362:ex:words:2:zh":"(topic)","grammar:2362:ex:words:2:pos":"particle","grammar:2362:ex:words:3:zh":"a thousand yen","grammar:2362:ex:words:3:note":"せんえん","grammar:2362:ex:words:3:pos":"noun","grammar:2362:ex:words:4:zh":"is","grammar:2362:ex:words:4:pos":"copula","grammar:2362:ex:points:0":"❗円（えん）: yen (the currency unit); note that the same character, read 「まる」, means a circle. Here it means yen.","grammar:2362:ex:points:1":"円（えん）: yen.","grammar:2362:ex2:trans":"I have 500 yen.","grammar:2362:ex2:structure":"五百円があります","grammar:2362:ex2:words:0:zh":"I","grammar:2362:ex2:words:0:note":"わたし","grammar:2362:ex2:words:0:pos":"pronoun","grammar:2362:ex2:words:1:zh":"(topic)","grammar:2362:ex2:words:1:pos":"particle","grammar:2362:ex2:words:2:zh":"500 yen","grammar:2362:ex2:words:2:note":"ごひゃくえん","grammar:2362:ex2:words:2:pos":"noun","grammar:2362:ex2:words:3:zh":"(nominative)","grammar:2362:ex2:words:3:pos":"particle","grammar:2362:ex2:words:4:zh":"there is / are","grammar:2362:ex2:words:4:pos":"verb","grammar:2362:ex2:points:0":"❗五百円: 500 yen.","grammar:2362:ex2:points:1":"五百円: 500 yen.","grammar:2362:ex3:trans":"I want to change money into yen.","grammar:2362:ex3:structure":"円を両替したいです","grammar:2362:ex3:words:0:zh":"yen","grammar:2362:ex3:words:0:note":"えん","grammar:2362:ex3:words:0:pos":"noun","grammar:2362:ex3:words:1:zh":"(object marker)","grammar:2362:ex3:words:1:pos":"particle","grammar:2362:ex3:words:2:zh":"want to exchange","grammar:2362:ex3:words:2:note":"りょうがえしたい","grammar:2362:ex3:words:2:pos":"verb","grammar:2362:ex3:words:3:zh":"(polite form)","grammar:2362:ex3:words:3:pos":"copula","grammar:2362:ex3:points:0":"❗両替する: to exchange (currency); 円を両替 = to change into yen.","grammar:2362:ex3:points:1":"両替する: to exchange (currency).","grammar:2362:ex4:trans":"I went to a 100-yen shop.","grammar:2362:ex4:structure":"百円ショップに行きました","grammar:2362:ex4:words:0:zh":"100-yen shop","grammar:2362:ex4:words:0:note":"ひゃくえんショップ","grammar:2362:ex4:words:0:pos":"noun","grammar:2362:ex4:words:1:zh":"(destination)","grammar:2362:ex4:words:1:pos":"particle","grammar:2362:ex4:words:2:zh":"went","grammar:2362:ex4:words:2:note":"いきました","grammar:2362:ex4:words:2:pos":"verb","grammar:2362:ex4:points:0":"❗百円ショップ: 100-yen shop (everything costs 100 yen; also called 「百均」).","grammar:2362:ex4:points:1":"百円ショップ: 100-yen shop.","grammar:2362:ex5:trans":"Japan's currency is the yen.","grammar:2362:ex5:structure":"日本の通貨は円です","grammar:2362:ex5:words:0:zh":"Japan","grammar:2362:ex5:words:0:note":"にほん","grammar:2362:ex5:words:0:pos":"noun","grammar:2362:ex5:words:1:zh":"'s","grammar:2362:ex5:words:1:pos":"particle","grammar:2362:ex5:words:2:zh":"currency","grammar:2362:ex5:words:2:note":"つうか","grammar:2362:ex5:words:2:pos":"noun","grammar:2362:ex5:words:3:zh":"(topic)","grammar:2362:ex5:words:3:pos":"particle","grammar:2362:ex5:words:4:zh":"yen","grammar:2362:ex5:words:4:note":"えん","grammar:2362:ex5:words:4:pos":"noun","grammar:2362:ex5:words:5:zh":"is","grammar:2362:ex5:words:5:pos":"copula","grammar:2362:ex5:points:0":"❗通貨: currency; 日本の通貨 = the yen.","grammar:2362:ex5:points:1":"通貨: currency.","exam:2362:zh":"You can buy this bread for 100 yen.","exam:2362:why":"「円」 is the unit of yen and can express price. 「歳」 expresses age, so it can't express a product's price."},"2363":{"example:2363:exzh":"This mat is very soft.","example:2363:exzh2":"Please clean the mat.","example:2363:exzh3":"I bought a new mat.","example:2363:exzh4":"I'm using a yoga mat.","example:2363:exzh5":"I like the color of this mat."},"2364":{"example:2364:exzh":"He has an important mission.","example:2364:exzh2":"My mission is to help people.","example:2364:exzh3":"I'll move forward with a sense of mission.","example:2364:exzh4":"Companies have a social mission.","example:2364:exzh5":"I'll work hard to fulfill his mission."},"2365":{"example:2365:exzh":"I received a visitor card at the front desk.","example:2365:exzh2":"Please write your name in the visitor register.","example:2365:exzh3":"There's a guide for visitors.","example:2365:exzh4":"Let's go check out the visitor center.","example:2365:exzh5":"Visitors check in at the front desk."},"2366":{"example:2366:exzh":"He abandoned the child."},"2367":{"example:2367:exzh":"This badge has a special meaning."},"2368":{"example:2368:exzh":"My grandfather is very kind.","grammar:2368:ex:trans":"My grandfather is very kind.","grammar:2368:ex:structure":"私の祖父はとても優しいです","grammar:2368:ex:words:0:zh":"I","grammar:2368:ex:words:0:note":"わたし","grammar:2368:ex:words:0:pos":"pronoun","grammar:2368:ex:words:1:zh":"'s","grammar:2368:ex:words:1:pos":"particle","grammar:2368:ex:words:2:zh":"grandfather","grammar:2368:ex:words:2:note":"そふ","grammar:2368:ex:words:2:pos":"noun","grammar:2368:ex:words:3:zh":"(topic)","grammar:2368:ex:words:3:pos":"particle","grammar:2368:ex:words:4:zh":"extremely","grammar:2368:ex:words:4:pos":"adverb","grammar:2368:ex:words:5:zh":"gentle","grammar:2368:ex:words:5:note":"やさしい","grammar:2368:ex:words:5:pos":"adjective","grammar:2368:ex:words:6:zh":"(polite form)","grammar:2368:ex:words:6:pos":"copula","grammar:2368:ex:points:0":"❗祖父（そふ）: (one's own) grandfather (humble form); for someone else's grandfather, or affectionately, use 「おじいさん／おじいちゃん」.","grammar:2368:ex:points:1":"祖父: grandfather."},"2369":{"example:2369:exzh":"The police officer keeps the city safe."},"2370":{"example:2370:exzh":"Her dress really stands out."},"2371":{"example:2371:exzh":"Sports are good for your health.","grammar:2371:ex:trans":"Sports are good for your health.","grammar:2371:ex:structure":"スポーツは健康に良いです","grammar:2371:ex:explain":"The pattern 「〜に良い」= good for…, beneficial to…, with the target marked by 「に」: 「健康に良い」= good for the health. In 「スポーツは…良いです」, 「は」 marks the topic and 「良い（いい）」 is an i-adjective. Whole sentence = Sports are good for your health. Key point: 「〜に良い／悪い」 expresses benefit or harm to something, and 「に」 marks the thing affected (健康に良い, 体に良い).","grammar:2371:ex:words:0:zh":"exercise","grammar:2371:ex:words:0:note":"loanword","grammar:2371:ex:words:0:pos":"noun","grammar:2371:ex:words:1:zh":"(topic)","grammar:2371:ex:words:1:pos":"particle","grammar:2371:ex:words:2:zh":"health","grammar:2371:ex:words:2:note":"けんこう","grammar:2371:ex:words:2:pos":"noun","grammar:2371:ex:words:3:zh":"(object)","grammar:2371:ex:words:3:pos":"particle","grammar:2371:ex:words:4:zh":"good","grammar:2371:ex:words:4:note":"よい","grammar:2371:ex:words:4:pos":"adjective","grammar:2371:ex:words:5:zh":"(polite form)","grammar:2371:ex:words:5:pos":"copula","grammar:2371:ex:points:0":"❗スポーツ: sports, exercise (sports); 〜に良い = good for…","grammar:2371:ex:points:1":"スポーツ: sports.","exam:2371:zh":"I like sports such as tennis and soccer.","exam:2371:why":"「スポーツ」 means sports and includes tennis and soccer. 「旅行」 is also a leisure activity, but it doesn't include these two sports."},"2373":{"example:2373:exzh":"Separation is sometimes necessary."},"2374":{"example:2374:exzh":"He is an accomplice in that crime.","example:2374:exzh2":"The accomplice was arrested.","example:2374:exzh3":"The police are looking for the accomplice.","example:2374:exzh4":"She was an accomplice in that plan.","example:2374:exzh5":"Evidence of an accomplice was found."},"2375":{"example:2375:exzh":"Victor is my friend.","example:2375:exzh2":"Victor came to the party.","example:2375:exzh3":"Victor is good at soccer.","example:2375:exzh4":"Victor likes traveling.","example:2375:exzh5":"Victor tells interesting stories."},"2376":{"example:2376:exzh":"There are many prostitutes in that area.","example:2376:exzh2":"We discussed the rights of prostitutes.","example:2376:exzh3":"She works as a prostitute.","example:2376:exzh4":"Life as a prostitute is hard.","example:2376:exzh5":"This movie is the story of a prostitute."},"2377":{"example:2377:exzh":"His face looks tired.","example:2377:exzh2":"When your face doesn't look good, you should rest.","example:2377:exzh3":"I recognize that face.","example:2377:exzh4":"Her face looks gentle.","example:2377:exzh5":"It's hard to hide your face."},"2378":{"example:2378:exzh":"This room is ten meters.","example:2378:exzh2":"It's about 500 meters to the station.","example:2378:exzh3":"We'll measure in meters.","example:2378:exzh4":"This tree is as tall as twenty meters.","example:2378:exzh5":"The road continues for fifty meters.","grammar:2378:ex:trans":"This room is ten meters.","grammar:2378:ex:structure":"This room is ten meters.","grammar:2378:ex:explain":"「メートル」 means meter. 「十メートル」 = ten meters. 「この部屋は…です」 is a copular sentence, stating a quantity plus unit directly as the predicate. The whole sentence = this room is ten meters. Key point: for units of length, use the loanword 「メートル」; 「〜は（quantity + unit）です」 can state a size or value directly.","grammar:2378:ex:words:0:zh":"this","grammar:2378:ex:words:0:pos":"pre-noun adjectival","grammar:2378:ex:words:1:zh":"room","grammar:2378:ex:words:1:note":"へや","grammar:2378:ex:words:1:pos":"noun","grammar:2378:ex:words:2:zh":"(topic)","grammar:2378:ex:words:2:pos":"particle","grammar:2378:ex:words:3:zh":"ten meters","grammar:2378:ex:words:3:note":"じゅうメートル","grammar:2378:ex:words:3:pos":"noun","grammar:2378:ex:words:4:zh":"is","grammar:2378:ex:words:4:pos":"copula","grammar:2378:ex:points:0":"❗メートル: meter; 十メートル = ten meters.","grammar:2378:ex:points:1":"メートル: meter.","grammar:2378:ex2:trans":"It's about five hundred meters to the station.","grammar:2378:ex2:structure":"〜までは〜メートルぐらいです","grammar:2378:ex2:words:0:zh":"station","grammar:2378:ex2:words:0:note":"えき","grammar:2378:ex2:words:0:pos":"noun","grammar:2378:ex2:words:1:zh":"until","grammar:2378:ex2:words:1:pos":"particle","grammar:2378:ex2:words:2:zh":"(topic)","grammar:2378:ex2:words:2:pos":"particle","grammar:2378:ex2:words:3:zh":"five hundred","grammar:2378:ex2:words:3:note":"ごひゃく","grammar:2378:ex2:words:3:pos":"numeral","grammar:2378:ex2:words:4:zh":"meters","grammar:2378:ex2:words:4:pos":"noun","grammar:2378:ex2:words:5:zh":"about","grammar:2378:ex2:words:5:pos":"particle","grammar:2378:ex2:words:6:zh":"(polite form)","grammar:2378:ex2:words:6:pos":"copula","grammar:2378:ex2:points:0":"❗五百メートル: a number plus メートル gives meters; 五百 is read ごひゃく.","grammar:2378:ex2:points:1":"〜まで: marks the endpoint, up to / as far as 〜.","grammar:2378:ex2:points:2":"ぐらい: after a quantity, means about / approximately.","grammar:2378:ex3:trans":"Measure using meters.","grammar:2378:ex3:structure":"Measure using meters.","grammar:2378:ex3:words:0:zh":"meters","grammar:2378:ex3:words:0:note":"loanword","grammar:2378:ex3:words:0:pos":"noun","grammar:2378:ex3:words:1:zh":"(object marker)","grammar:2378:ex3:words:1:pos":"particle","grammar:2378:ex3:words:2:zh":"use","grammar:2378:ex3:words:2:note":"つかって","grammar:2378:ex3:words:2:pos":"verb","grammar:2378:ex3:words:3:zh":"measure","grammar:2378:ex3:words:3:note":"そくていします","grammar:2378:ex3:words:3:pos":"verb","grammar:2378:ex3:points:0":"❗メートルを使う: to measure in meters.","grammar:2378:ex3:points:1":"メートルで測定: measuring in meters.","grammar:2378:ex4:trans":"This tree is a full twenty meters tall.","grammar:2378:ex4:structure":"This tree is a full twenty meters tall.","grammar:2378:ex4:words:0:zh":"this","grammar:2378:ex4:words:0:pos":"pre-noun adjectival","grammar:2378:ex4:words:1:zh":"tree","grammar:2378:ex4:words:1:note":"き","grammar:2378:ex4:words:1:pos":"noun","grammar:2378:ex4:words:2:zh":"(topic)","grammar:2378:ex4:words:2:pos":"particle","grammar:2378:ex4:words:3:zh":"twenty meters","grammar:2378:ex4:words:3:note":"にじゅうメートル","grammar:2378:ex4:words:3:pos":"noun","grammar:2378:ex4:words:4:zh":"as much as","grammar:2378:ex4:words:4:pos":"particle","grammar:2378:ex4:words:5:zh":"tall","grammar:2378:ex4:words:5:note":"たかい","grammar:2378:ex4:words:5:pos":"adjective","grammar:2378:ex4:points:0":"❗〜も: as much as… (emphasizes how large the quantity is); 二十メートルも = as much as twenty meters.","grammar:2378:ex4:points:1":"〜も高い: as tall as.","grammar:2378:ex5:trans":"The road continues for fifty meters.","grammar:2378:ex5:structure":"The road continues for fifty meters.","grammar:2378:ex5:words:0:zh":"road","grammar:2378:ex5:words:0:note":"どうろ","grammar:2378:ex5:words:0:pos":"noun","grammar:2378:ex5:words:1:zh":"(topic)","grammar:2378:ex5:words:1:pos":"particle","grammar:2378:ex5:words:2:zh":"fifty meters","grammar:2378:ex5:words:2:note":"ごじゅうメートル","grammar:2378:ex5:words:2:pos":"noun","grammar:2378:ex5:words:3:zh":"continues","grammar:2378:ex5:words:3:note":"つづいている","grammar:2378:ex5:words:3:pos":"verb","grammar:2378:ex5:points:0":"❗〜メートル続く: to extend for … meters (続く is an intransitive verb).","grammar:2378:ex5:points:1":"メートル続く: to extend for meters."},"2379":{"example:2379:exzh":"Please pay in cash.","example:2379:exzh2":"The payment deadline is tomorrow.","example:2379:exzh3":"I paid by credit card.","example:2379:exzh4":"This payment is important.","example:2379:exzh5":"Please don't forget to pay."},"2380":{"example:2380:exzh":"He's imitating her.","example:2380:exzh2":"Imitating someone is hard.","example:2380:exzh3":"Imitating your friends is fun.","example:2380:exzh4":"Please don't imitate her.","example:2380:exzh5":"Imitating is important."},"2381":{"example:2381:exzh":"This column contains data.","example:2381:exzh2":"We need to add a column.","example:2381:exzh3":"I organized the columns in the report.","example:2381:exzh4":"Understand the meaning of each column.","example:2381:exzh5":"Let's count the number of columns."},"2382":{"example:2382:exzh":"It can't be helped, so I'll give up.","example:2382:exzh2":"Let's think of a new way.","example:2382:exzh3":"That way won't work.","example:2382:exzh4":"We need to change the method.","example:2382:exzh5":"Please tell me the method.","grammar:2382:ex:trans":"Since there's nothing else I can do, I'll give up.","grammar:2382:ex:structure":"Since there's nothing else I can do, I'll give up.","grammar:2382:ex:explain":"「仕方（しかた）」 = way, method. The set phrase 「仕方がない」 = there's nothing to be done, it can't be helped; it is a very common fixed expression. 「〜ので」 marks the reason = because…. The whole sentence = since there's nothing else I can do, I'll give up. Key point: 「仕方がない／しょうがない」 is a stock phrase for accepting something you can't change; 「ので」 gives a causal tone that is objective and soft.","grammar:2382:ex:words:0:zh":"way, method","grammar:2382:ex:words:0:note":"しかた","grammar:2382:ex:words:0:pos":"noun","grammar:2382:ex:words:1:zh":"(nominative)","grammar:2382:ex:words:1:pos":"particle","grammar:2382:ex:words:2:zh":"don't have","grammar:2382:ex:words:2:pos":"adjective","grammar:2382:ex:words:3:zh":"because","grammar:2382:ex:words:3:pos":"particle","grammar:2382:ex:words:4:zh":"give up","grammar:2382:ex:words:4:note":"あきらめます","grammar:2382:ex:words:4:pos":"verb","grammar:2382:ex:points:0":"❗仕方（しかた）: way, method (= やり方); 仕方がない = there's nothing to be done, it can't be helped (fixed phrase).","grammar:2382:ex:points:1":"仕方: way.","grammar:2382:ex2:trans":"Let's think of a new way.","grammar:2382:ex2:structure":"Let's think of a new way.","grammar:2382:ex2:words:0:zh":"new","grammar:2382:ex2:words:0:note":"あたらしい","grammar:2382:ex2:words:0:pos":"adjective","grammar:2382:ex2:words:1:zh":"way, method","grammar:2382:ex2:words:1:note":"しかた","grammar:2382:ex2:words:1:pos":"noun","grammar:2382:ex2:words:2:zh":"(object marker)","grammar:2382:ex2:words:2:pos":"particle","grammar:2382:ex2:words:3:zh":"let's think","grammar:2382:ex2:words:3:note":"かんがえよう","grammar:2382:ex2:words:3:pos":"verb","grammar:2382:ex2:points:0":"❗新しい仕方: a new way, a new approach.","grammar:2382:ex2:points:1":"新しい仕方: a new way.","grammar:2382:ex3:trans":"That way won't work.","grammar:2382:ex3:structure":"That way won't work.","grammar:2382:ex3:words:0:zh":"that","grammar:2382:ex3:words:0:pos":"pre-noun adjectival","grammar:2382:ex3:words:1:zh":"way, method","grammar:2382:ex3:words:1:note":"しかた","grammar:2382:ex3:words:1:pos":"noun","grammar:2382:ex3:words:2:zh":"(condition)","grammar:2382:ex3:words:2:pos":"particle","grammar:2382:ex3:words:3:zh":"won't work","grammar:2382:ex3:words:3:pos":"set phrase","grammar:2382:ex3:points:0":"❗うまくいかない: to not go well, to not work out (fixed phrase); その仕方では = if you do it that way.","grammar:2382:ex3:points:1":"うまくいかない: won't work.","grammar:2382:ex4:trans":"It's necessary to change the way it's done.","grammar:2382:ex4:structure":"It's necessary to change the way it's done.","grammar:2382:ex4:words:0:zh":"way, method","grammar:2382:ex4:words:0:note":"しかた","grammar:2382:ex4:words:0:pos":"noun","grammar:2382:ex4:words:1:zh":"(object marker)","grammar:2382:ex4:words:1:pos":"particle","grammar:2382:ex4:words:2:zh":"change","grammar:2382:ex4:words:2:note":"かえる","grammar:2382:ex4:words:2:pos":"verb","grammar:2382:ex4:words:3:zh":"necessary","grammar:2382:ex4:words:3:note":"ひつよう","grammar:2382:ex4:words:3:pos":"noun","grammar:2382:ex4:words:4:zh":"(nominative)","grammar:2382:ex4:words:4:pos":"particle","grammar:2382:ex4:words:5:zh":"there is / are","grammar:2382:ex4:words:5:pos":"verb","grammar:2382:ex4:points:0":"❗仕方を変える: to change the approach.","grammar:2382:ex4:points:1":"仕方を変える: change the method.","grammar:2382:ex5:trans":"Please tell me how to do it.","grammar:2382:ex5:structure":"Please tell me how to do it.","grammar:2382:ex5:words:0:zh":"way, method","grammar:2382:ex5:words:0:note":"しかた","grammar:2382:ex5:words:0:pos":"noun","grammar:2382:ex5:words:1:zh":"(object marker)","grammar:2382:ex5:words:1:pos":"particle","grammar:2382:ex5:words:2:zh":"tell","grammar:2382:ex5:words:2:note":"おしえて","grammar:2382:ex5:words:2:pos":"verb","grammar:2382:ex5:words:3:zh":"please","grammar:2382:ex5:words:3:pos":"auxiliary verb","grammar:2382:ex5:points:0":"❗仕方を教える: to teach someone how to do something; 「〜の仕方」 (= how to …) is also common.","grammar:2382:ex5:points:1":"仕方を教える: teach how to do it."},"2383":{"example:2383:exzh":"He likes adventure.","example:2383:exzh2":"Going on adventures is fun.","example:2383:exzh3":"Let's start a new adventure.","example:2383:exzh4":"I heard a story about an adventure.","example:2383:exzh5":"You grow through adventure."},"2384":{"example:2384:exzh":"It's hot today.","example:2384:exzh2":"I like the hot season.","example:2384:exzh3":"On hot days, I drink a lot of water.","example:2384:exzh4":"It's very hot outside.","example:2384:exzh5":"Please be careful on hot days.","grammar:2384:ex:trans":"It's hot today.","grammar:2384:ex:structure":"〜は暑いです","grammar:2384:ex:explain":"In 「今日は暑いです」, 「は」 makes today the topic, and 「暑い（あつい）」 is an i-adjective that specifically means the weather is hot. Distinguish it from the homophone 「熱い」 (things hot to the touch, or a fever): use 「暑い」 for hot weather and 「熱い」 for hot objects. The whole sentence means it's hot today. Key point: 「暑い」 (climate) and 「熱い」 (objects, high temperature) sound the same but are written differently and used differently.","grammar:2384:ex:words:0:zh":"today","grammar:2384:ex:words:0:note":"きょう","grammar:2384:ex:words:0:pos":"noun","grammar:2384:ex:words:1:zh":"(topic)","grammar:2384:ex:words:1:pos":"particle","grammar:2384:ex:words:2:zh":"hot","grammar:2384:ex:words:2:note":"あつい","grammar:2384:ex:words:2:pos":"adjective","grammar:2384:ex:words:3:zh":"(polite form)","grammar:2384:ex:words:3:pos":"copula","grammar:2384:ex:points:0":"❗暑い（あつい）: hot (weather); vs 熱い (hot to the touch).","grammar:2384:ex:points:1":"今日は暑い: it's hot today.","grammar:2384:ex2:trans":"I like the hot season.","grammar:2384:ex2:structure":"〜が好きです","grammar:2384:ex2:words:0:zh":"hot","grammar:2384:ex2:words:0:note":"あつい","grammar:2384:ex2:words:0:pos":"adjective","grammar:2384:ex2:words:1:zh":"season","grammar:2384:ex2:words:1:note":"きせつ","grammar:2384:ex2:words:1:pos":"noun","grammar:2384:ex2:words:2:zh":"(object)","grammar:2384:ex2:words:2:pos":"particle","grammar:2384:ex2:words:3:zh":"to like","grammar:2384:ex2:words:3:note":"すき","grammar:2384:ex2:words:3:pos":"na-adjective","grammar:2384:ex2:words:4:zh":"(polite form)","grammar:2384:ex2:words:4:pos":"copula","grammar:2384:ex2:points:0":"暑い季節: the hot season.","grammar:2384:ex2:points:1":"〜が好き: to like …","grammar:2384:ex3:trans":"On hot days I drink a lot of water.","grammar:2384:ex3:structure":"暑い日に〜を飲みます","grammar:2384:ex3:words:0:zh":"hot","grammar:2384:ex3:words:0:note":"あつい","grammar:2384:ex3:words:0:pos":"adjective","grammar:2384:ex3:words:1:zh":"day","grammar:2384:ex3:words:1:note":"ひ","grammar:2384:ex3:words:1:pos":"noun","grammar:2384:ex3:words:2:zh":"(point in time)","grammar:2384:ex3:words:2:pos":"particle","grammar:2384:ex3:words:3:zh":"water","grammar:2384:ex3:words:3:note":"みず","grammar:2384:ex3:words:3:pos":"noun","grammar:2384:ex3:words:4:zh":"(object marker)","grammar:2384:ex3:words:4:pos":"particle","grammar:2384:ex3:words:5:zh":"a lot","grammar:2384:ex3:words:5:pos":"adverb","grammar:2384:ex3:words:6:zh":"to drink","grammar:2384:ex3:words:6:note":"のみます","grammar:2384:ex3:words:6:pos":"verb","grammar:2384:ex3:points:0":"暑い日に: on a hot day.","grammar:2384:ex3:points:1":"水を飲む: to drink water.","grammar:2384:ex4:trans":"It's very hot outside.","grammar:2384:ex4:structure":"〜はとても暑いです","grammar:2384:ex4:words:0:zh":"outside","grammar:2384:ex4:words:0:note":"そと","grammar:2384:ex4:words:0:pos":"noun","grammar:2384:ex4:words:1:zh":"(topic)","grammar:2384:ex4:words:1:pos":"particle","grammar:2384:ex4:words:2:zh":"extremely","grammar:2384:ex4:words:2:pos":"adverb","grammar:2384:ex4:words:3:zh":"hot","grammar:2384:ex4:words:3:note":"あつい","grammar:2384:ex4:words:3:pos":"adjective","grammar:2384:ex4:words:4:zh":"(polite form)","grammar:2384:ex4:words:4:pos":"copula","grammar:2384:ex4:points:0":"外は暑い: it's hot outside.","grammar:2384:ex4:points:1":"「とても」: very.","grammar:2384:ex5:trans":"Please be careful on hot days.","grammar:2384:ex5:structure":"暑い日は気をつけてください","grammar:2384:ex5:explain":"「暑い」 modifies 「日」 directly, and 「は」 sets hot days as the situation the warning applies to. 「気をつける」 should be understood as a whole, meaning to be careful or watch out; don't translate it literally as putting one's mind on something. 「つけてください」 uses the te-form to make a request, asking the other person to be careful.","grammar:2384:ex5:words:0:zh":"hot (weather)","grammar:2384:ex5:words:0:note":"あつい","grammar:2384:ex5:words:0:pos":"i-adjective","grammar:2384:ex5:words:1:zh":"day","grammar:2384:ex5:words:1:note":"ひ","grammar:2384:ex5:words:1:pos":"noun","grammar:2384:ex5:words:2:zh":"(topic; sets up the situation)","grammar:2384:ex5:words:2:pos":"particle","grammar:2384:ex5:words:3:zh":"care, attention","grammar:2384:ex5:words:3:note":"き","grammar:2384:ex5:words:3:pos":"noun","grammar:2384:ex5:words:4:zh":"(object)","grammar:2384:ex5:words:4:pos":"particle","grammar:2384:ex5:words:5:zh":"be mindful of","grammar:2384:ex5:words:5:pos":"verb","grammar:2384:ex5:words:6:zh":"(links to the request expression)","grammar:2384:ex5:words:6:pos":"particle","grammar:2384:ex5:words:7:zh":"please","grammar:2384:ex5:words:7:pos":"verb","grammar:2384:ex5:points:0":"「暑い」 describes hot weather and is different from 「熱い」, which describes objects that are hot to the touch.","grammar:2384:ex5:points:1":"「気をつける」 is a set phrase meaning to be careful or pay attention.","grammar:2384:ex5:points:2":"「〜てください」 asks someone to do something.","exam:2384:zh":"Today the temperature is as high as 35 degrees and it's hot, so I want to drink cold water.","exam:2384:why":"「暑い」 describes temperatures that feel hot. 「暖かい」 means warm, and usually doesn't carry the feeling of being so hot you want cold water."},"2385":{"example:2385:exzh":"They're trying to start a revolution.","example:2385:exzh2":"The revolution had a huge impact on history.","example:2385:exzh3":"This idea is revolutionary.","example:2385:exzh4":"His actions sparked a revolution.","example:2385:exzh5":"The revolution will open up a new future."},"2386":{"example:2386:exzh":"This project needs financing.","example:2386:exzh2":"There are conditions for getting financing.","example:2386:exzh3":"He's a financing expert.","example:2386:exzh4":"The financing paperwork is complicated.","example:2386:exzh5":"Financing for the new business was approved."},"2387":{"example:2387:exzh":"The desert is vast and beautiful.","example:2387:exzh2":"There's almost no water in the desert.","example:2387:exzh3":"He traveled through the desert.","example:2387:exzh4":"Desert nights are very quiet.","example:2387:exzh5":"Desert temperatures change a lot between day and night."},"2388":{"example:2388:exzh":"I got a driver's license.","example:2388:exzh2":"You can't drive without a license.","example:2388:exzh3":"He has a teaching license.","example:2388:exzh4":"Renewing a license is easy.","example:2388:exzh5":"I'm studying to get a license."},"2389":{"example:2389:exzh":"We plan to build a new bridge.","example:2389:exzh2":"This factory makes cars.","example:2389:exzh3":"He's good at building houses.","example:2389:exzh4":"I'll gather the materials for building.","example:2389:exzh5":"Someone taught me how to build a boat."},"2390":{"example:2390:exzh":"The students are wearing uniforms.","example:2390:exzh2":"This uniform looks really cool.","example:2390:exzh3":"My school's uniform is blue.","example:2390:exzh4":"The uniform design was changed.","example:2390:exzh5":"He takes pride in his workplace uniform."},"2391":{"example:2391:exzh":"His country is a republic.","example:2391:exzh2":"We will talk about the Republican Party's policies.","example:2391:exzh3":"A republic values equality.","example:2391:exzh4":"Many countries have adopted republican government.","example:2391:exzh5":"Republican government guarantees citizens' freedom."},"2392":{"example:2392:exzh":"He plays an important role on the team.","example:2392:exzh2":"Everyone has a role in this project.","example:2392:exzh3":"It's important to divide up roles.","example:2392:exzh4":"She carries out her role properly.","example:2392:exzh5":"Understanding your role is the key to success."},"2393":{"example:2393:exzh":"That's all I have to discuss.","example:2393:exzh2":"If you have any business to discuss, please let me know.","example:2393:exzh3":"I'll get the matters to discuss in order.","example:2393:exzh4":"I'll jot down the business later.","example:2393:exzh5":"Once I'm done with my business, I'll go home right away."},"2394":{"example:2394:exzh":"My nails have grown out.","example:2394:exzh2":"She likes cutting her nails.","example:2394:exzh3":"Please be careful not to damage your nails.","example:2394:exzh4":"I tried painting my nails.","example:2394:exzh5":"It's important to take good care of your nails as they grow."},"2395":{"example:2395:exzh":"This hoodie is very warm.","example:2395:exzh2":"I'm planning to buy a new hoodie.","example:2395:exzh3":"My friend and I wore matching hoodies.","example:2395:exzh4":"In winter I wear a thick hoodie.","example:2395:exzh5":"I often wear a hoodie when I exercise."},"2396":{"example:2396:exzh":"It's hard to reach a conclusion.","example:2396:exzh2":"A conclusion on this problem hasn't been reached yet.","example:2396:exzh3":"After his explanation, the conclusion became clear.","example:2396:exzh4":"To sum up, we succeeded.","example:2396:exzh5":"We drew a conclusion from many opinions."},"2397":{"example:2397:exzh":"The phone rang while I was studying.","example:2397:exzh2":"The conversation started in the middle of the meal.","example:2397:exzh3":"An email arrived in the middle of work.","example:2397:exzh4":"It's rude to leave your seat in the middle of a presentation.","example:2397:exzh5":"It started raining on the way out to have fun."}};